/* Taller o Formación según la duración: con menos horas que el mínimo es Taller; con ese mínimo o más, Formación */
const horasMinFormacion = (datos) => Number(datos && datos.config && datos.config.horasMinFormacion) || 8;
const claseActividad = (horas, datos) => (Number(horas) > 0 ? (Number(horas) < horasMinFormacion(datos) ? 'TALLER' : 'FORMACION') : '');
const CLASES_ACTIVIDAD = { TALLER: 'Taller', FORMACION: 'Formación', PROGRAMA: 'Programa', CAPACITACION: 'Capacitación' };
const CLASES_ELEGIBLES = [{ id: '', texto: 'Automática según las horas (Taller o Formación)' }, { id: 'PROGRAMA', texto: 'Programa' }, { id: 'CAPACITACION', texto: 'Capacitación' }];
/* Modalidad de una actividad del catálogo o de un taller: la elegida al registrar (Programa o Capacitación) o la que resulta de las horas */
const claseDe = (it, datos) => (it && (it.clase === 'PROGRAMA' || it.clase === 'CAPACITACION') ? it.clase : claseActividad(it && it.horas, datos));
const textoClase = (it, datos) => CLASES_ACTIVIDAD[claseDe(it, datos)] || '—';

