/* Un ítem por proceso de la descripción de cargo vigente (se suma a los ítems generales del hito) */
const SECCION_FUNCIONES_DC = 'Funciones del cargo (descripción de cargo)';
function itemsFuncionesCargo(cargoId, marca) {
  const d = descripcionDe(cargoId, marca);
  return d ? d.procesos.map((x, i) => ({ id: `dc${i + 1}`, seccion: SECCION_FUNCIONES_DC, texto: x.proceso, ayuda: x.funciones.slice(0, 3).join(' · ') })) : [];
}
function itemsHito(hitoId, marca, cargoId) {
  /* Pase a fijo (solo tienda): formato oficial de la empresa, con sus 9 factores */
  if (hitoId === 'FIJO') return ITEMS_FIJO_OFICIAL;
  return itemsHitoBase(hitoId, marca, cargoId);
}
/* Ítems generales del hito (modelo anterior; las evaluaciones antiguas de pase a fijo se leen con él) */
function itemsHitoBase(hitoId, marca, cargoId) {
  const base = hitoId === 'PRUEBA' ? ITEMS_PRUEBA : hitoId === 'PROSECUCION' ? ITEMS_DESEMPENO_CONTRATO : [...ITEMS_DESEMPENO_CONTRATO, ...itemsCultura(MARCAS[marca] || 'Balú')];
  return cargoId ? [...base, ...itemsFuncionesCargo(cargoId, marca)] : base;
}
/* Ítems con que se hizo una evaluación: los guardados en ella (desde v1.8.0) o, en las anteriores, los generales del hito */
function itemsDeEval(d, trab) { return Array.isArray(d.items) && d.items.length ? d.items : itemsHitoBase(d.hito, trab ? trab.marca : 'BALU'); }
const esEvalFijoOficial = (d) => Boolean(d && d.modelo === MODELO_FIJO_OFICIAL);
const valorEval = (d, v) => (esEvalFijoOficial(d) ? `${siglaFijo(v)}` : String(v));


