const ESTADOS_ABIERTOS = ['PENDIENTE', 'EN_REVISION', 'APROBADA', 'DEVUELTA'];
/* Un trabajador egresado no queda activo en ningún módulo: no se le asignan tareas, pruebas, evaluaciones ni planes. */
const estaEgresado = (datos, trabajadorId) => { const tr = ((datos && datos.trabajadores) || []).find((x) => x.id === trabajadorId); return Boolean(tr) && tr.estatus === 'EGRESADO'; };
/* Al ejecutarse el egreso se cierran sus pendientes abiertos (solicitudes, sucesión y accesos a pruebas) con constancia en el historial. */
function cerrarPendientesPorEgreso(d, trabajadorId, solicitudOrigenId, fecha, usuarioId) {
  const nota = 'Cerrada automáticamente: el trabajador egresó.';
  return {
    ...d,
    solicitudes: d.solicitudes.map((x) => (x.trabajadorId === trabajadorId && x.id !== solicitudOrigenId && ESTADOS_ABIERTOS.includes(x.estado)
      ? { ...x, estado: 'RECHAZADA', cerradaPorEgreso: true, eventos: [...x.eventos, { fecha, usuarioId, accion: 'RECHAZADA', comentario: nota }] } : x)),
    nominaciones: (d.nominaciones || []).map((n) => (n.candidatoId === trabajadorId && ['SUGERIDO', 'PROPUESTO', 'APROBADO_RRHH', 'APROBADO', 'REGISTRADO'].includes(n.estado)
      ? { ...n, estado: 'RECHAZADO', historial: [...(n.historial || []), { fecha, usuarioId, accion: 'RECHAZAR', estado: 'RECHAZADO', comentario: 'El trabajador egresó' }] } : n)),
    accesosPrueba: (d.accesosPrueba || []).map((a) => (a.trabajadorId === trabajadorId && ['PENDIENTE', 'EN_CURSO', 'BLOQUEADA'].includes(a.estado) ? { ...a, estado: 'ANULADA' } : a)),
  };
}

