function leerEstructuraAdm() { try { const t = window.localStorage.getItem(CLAVE_LOCAL_ADM); return t ? JSON.parse(t) : null; } catch (e) { return null; } }
function guardarEstructuraAdm(o) { try { window.localStorage.setItem(CLAVE_LOCAL_ADM, JSON.stringify(o)); return true; } catch (e) { return false; } }
