function resultadoEvalContrato(respuestas, items) {
  const promedio = redondear2(respuestas.reduce((a, v) => a + Number(v), 0) / respuestas.length);
  const r = { promedio, puntaje: redondear2(promedio * 2), secciones: [] };
  if (items) {
    const nombres = Array.from(new Set(items.map((x) => x.seccion)));
    r.secciones = nombres.map((n) => {
      const vals = items.map((it, i) => (it.seccion === n ? Number(respuestas[i]) : null)).filter((v) => v !== null);
      return { nombre: n, promedio: redondear2(vals.reduce((a, v) => a + v, 0) / vals.length) };
    });
  }
  return r;
}
