          <div className="mt-2 flex flex-wrap gap-2">{accionesPosibles.map((a) => <Boton key={a} tamano="sm" variante={a === 'RECHAZAR' ? 'peligro' : 'primario'} onClick={() => ejecutar(a)}>{TEXTO_ACCION_NOMINACION[a]}</Boton>)}</div>
