    dispatch({ type: 'GUARDAR_PDI', payload: { pdi, bitacora: registro(usuario.id, existente ? 'EDITAR' : 'CREAR', 'Plan de desarrollo individual', pdi.id, `${tr.nombres} ${tr.apellidos}: ${accs.length} acciones`) } });
