      const cargosOk = new Set(['GT', 'SUB', 'CAJT', 'CAJ', 'JALM', 'VM', 'ALM', 'ASE']);
      const trabajadores = fichas.filter((f) => f.tiendaId && tiendasBalu.has(f.tiendaId) && cargosOk.has(f.cargoId)).map((f) => ({ id: `F-${f.id}`, marca: MARCA_SUCESION, tiendaId: f.tiendaId, cargoId: f.cargoId, nombres: f.nombres, apellidos: f.apellidos, cedula: `${f.letra || 'V'}-${f.id}`, fechaIngreso: '', estatus: 'ACTIVO', contrato: { tipo: 'DETERMINADO', hitos: {} }, historial: [] }));
