/* ---------- Resultados consolidados de evaluaciones ---------- */
function ResultadosEvaluaciones({ filtroTienda, plegable = false }) {
  const { datos, usuario, nombreTienda } = useApp();
  const per = usePeriodo('anio');
  const enResumen = useContext(PlegadoCtx);
  const [abiertoLocal, setAbierto] = useState(!plegable);
  const abierto = enResumen || abiertoLocal;
  if (usuario.rol === 'tienda') return null;
  const en = (ti) => enAlcance(usuario, ti) && (!filtroTienda || filtroTienda(ti));
  const dentro = (f) => !per.error && f && f.slice(0, 10) >= per.desde && f.slice(0, 10) <= per.hasta;
  const filas = []; const porTienda = {};
  const sumar = (ti, ap, rep) => { porTienda[ti] = porTienda[ti] || { id: ti, nombre: nombreTienda(ti), aprueban: 0, reprueban: 0 }; porTienda[ti].aprueban += ap; porTienda[ti].reprueban += rep; };
  HITOS_CONTRATO.forEach((h) => {
    const xs = datos.solicitudes.filter((s) => s.tipo === h.tipo && s.estado !== 'RECHAZADA' && en(tiendaDeSolicitud(s, datos)) && dentro(s.fechaCreacion));
    const cerr = xs.filter((s) => s.estado === 'EJECUTADA');
    const ap = cerr.filter((s) => s.datosPropuestos.decision === 'CONTINUA'); const rep = cerr.filter((s) => s.datosPropuestos.decision === 'NO_CONTINUA');
    ap.forEach((s) => sumar(tiendaDeSolicitud(s, datos), 1, 0)); rep.forEach((s) => sumar(tiendaDeSolicitud(s, datos), 0, 1));
    filas.push({ id: h.id, nombre: h.corto, aprueban: ap.length, reprueban: rep.length, proceso: xs.length - cerr.length, nota: `Reprobados en aprobación: ${xs.filter((s) => s.estado !== 'EJECUTADA' && s.datosPropuestos.decision === 'NO_CONTINUA').length}` });
  });
  const umbral = Number(datos.config.umbralAprobacion) || 7;
  const nb = (datos.evaluaciones || []).filter((e) => en(e.tiendaId) && dentro(e.fecha) && e.estadoAprobacion !== 'RECHAZADA');
  const nbCerr = nb.filter((e) => e.estadoAprobacion === 'APROBADA');
  const nbAp = nbCerr.filter((e) => e.puntaje >= umbral);
  nbAp.forEach((e) => sumar(e.tiendaId, 1, 0)); nbCerr.filter((e) => e.puntaje < umbral).forEach((e) => sumar(e.tiendaId, 0, 1));
  filas.push({ id: 'NINEBOX', nombre: 'Nine-Box (Gerentes y Subgerentes)', aprueban: nbAp.length, reprueban: nbCerr.length - nbAp.length, proceso: nb.length - nbCerr.length, nota: `Aprueba con puntaje ≥ ${fmtNum(umbral, 1)}` });
  const minNota = Number(datos.config.notaMinimaPruebas) || 70;
  const pr = (datos.resultadosPruebas || []).filter((r) => { const tr = datos.trabajadores.find((x) => x.id === r.trabajadorId); return tr && en(tr.tiendaId) && dentro(r.fecha); });
  const prAp = pr.filter((r) => (r.puntaje / (r.puntajeMax || 100)) * 100 >= minNota);
  pr.forEach((r) => { const tr = datos.trabajadores.find((x) => x.id === r.trabajadorId); const ok = (r.puntaje / (r.puntajeMax || 100)) * 100 >= minNota; sumar(tr.tiendaId, ok ? 1 : 0, ok ? 0 : 1); });
  filas.push({ id: 'PRUEBAS', nombre: 'Pruebas de conocimiento, desempeño y actuación', aprueban: prAp.length, reprueban: pr.length - prAp.length, proceso: 0, nota: `Aprueba con ${minNota}% o más` });
  const tot = filas.reduce((a, x) => ({ ap: a.ap + x.aprueban, rep: a.rep + x.reprueban }), { ap: 0, rep: 0 });
  const pct = (a, r) => (a + r ? `${fmtNum((a / (a + r)) * 100, 0)}%` : '—');
  return (
    <Panel className="mt-4" titulo={enResumen ? 'Resultados de evaluaciones' : `Resultados de evaluaciones (consolidado)${abierto ? '' : ' · año en curso'}`} tono={tot.rep ? 'alerta' : undefined}
      resumen={`${cuenta(tot.ap, 'aprueba', 'aprueban')} · ${cuenta(tot.rep, 'reprueba', 'reprueban')} · ${filas.reduce((a, x) => a + x.proceso, 0)} en proceso`} accion={plegable && !enResumen ? <BotonDetalle abierto={abierto} onClick={() => setAbierto((v) => !v)} /> : null}>
      {abierto ? <div className="mb-3">{per.controles('re')}</div> : null}
      <div className="mb-3 grid grid-cols-2 gap-3 lg:grid-cols-3">
        <Indicador icono={CheckCircle2} titulo="Aprueban" valor={String(tot.ap)} detalle={`Tasa de aprobación ${pct(tot.ap, tot.rep)}`} formula="Evaluaciones cerradas con resultado aprobatorio en el período." />
        <Indicador icono={XCircle} titulo="Reprueban" valor={String(tot.rep)} detalle="Evaluaciones cerradas" tono={tot.rep ? 'alerta' : 'normal'} formula="Evaluaciones cerradas con resultado no aprobatorio en el período." />
        <Indicador icono={Clock} titulo="En proceso" valor={String(filas.reduce((a, x) => a + x.proceso, 0))} detalle="Aún en la ruta de aprobación" formula="Evaluaciones enviadas que no han completado su aprobación." />
      </div>
      {abierto ? (
      <div className="grid grid-cols-1 gap-4 xl:grid-cols-2">
        <Tabla filas={filas} columnas={[
          { clave: 'nombre', titulo: 'Evaluación', render: (x) => <span title={x.nota}>{x.nombre}</span> },
          { clave: 'aprueban', titulo: 'Aprueban', clase: 'text-right tabular-nums', render: (x) => String(x.aprueban) },
          { clave: 'reprueban', titulo: 'Reprueban', clase: 'text-right tabular-nums', render: (x) => <span className={x.reprueban ? 'font-semibold text-[#B42318]' : ''}>{String(x.reprueban)}</span> },
          { clave: 'proceso', titulo: 'En proceso', clase: 'text-right tabular-nums', render: (x) => String(x.proceso) },
          { clave: 'pct', titulo: '% aprob.', clase: 'text-right tabular-nums', render: (x) => pct(x.aprueban, x.reprueban) },
        ]} />
        <Tabla filas={Object.values(porTienda).sort((a, b) => b.reprueban - a.reprueban || a.nombre.localeCompare(b.nombre))} vacio={<EstadoVacio icono={ClipboardCheck} titulo="Sin evaluaciones cerradas en el período" />} columnas={[
          { clave: 'nombre', titulo: 'Tienda' },
          { clave: 'aprueban', titulo: 'Aprueban', clase: 'text-right tabular-nums', render: (x) => String(x.aprueban) },
          { clave: 'reprueban', titulo: 'Reprueban', clase: 'text-right tabular-nums', render: (x) => String(x.reprueban) },
          { clave: 'pct', titulo: '% aprob.', clase: 'text-right tabular-nums', render: (x) => pct(x.aprueban, x.reprueban) },
        ]} />
      </div>
      ) : null}
    </Panel>
  );
}

/* ---------- Nube: datos, diferencias y pantallas de acceso ---------- */
const COLECCIONES_NUBE = ['tiendas', 'cargos', 'trabajadores', 'evaluaciones', 'solicitudes', 'documentos', 'precargados', 'resultadosPruebas', 'amonestaciones', 'bitacora', 'modelosCompensacion', 'concursos', 'onboarding', 'entrevistasSalida', 'talleres', 'catalogoFormaciones', 'participaciones', 'nominaciones', 'pdi', 'fotosSucesion', 'climaCiclos', 'climaRespuestas', 'requisiciones'];
const AJUSTES_NUBE = ['config', 'plantillas', 'hcNecesario', 'montosApoyo', 'pruebas', 'pruebasTraslado', 'plantillasOnboarding', 'ipvPreguntas', 'cumplimientoDiscapacidad'];
function ajustesPorDefecto() {
  return {
    config: { ...CONFIG_INICIAL },
    plantillas: JSON.parse(JSON.stringify(PLANTILLAS_INICIALES)),
    /* Versión publicada: no se define un mínimo para Balú. Solo Planeta trae HC aprobado (reporte de estructura 2026); el resto se proyecta con la plantilla existente. */
    hcNecesario: { porFormato: hcFormatosVacios(), porTienda: JSON.parse(JSON.stringify(HC_APROBADO_PLANETA_2026)), temporada: { porFormato: hcFormatosVacios(), porTienda: JSON.parse(JSON.stringify(HC_APROBADO_PLANETA_2026)) } },
    montosApoyo: { ...MONTOS_APOYO_INICIALES },
    pruebas: PRUEBAS_INICIALES.map((x) => ({ ...x })),
    pruebasTraslado: [...PRUEBAS_TRASLADO_INICIALES],
    plantillasOnboarding: JSON.parse(JSON.stringify(PLANTILLAS_ONBOARDING_INICIALES)),
    ipvPreguntas: IPV_CUADERNILLO.map((x) => ({ ...x })),
    cumplimientoDiscapacidad: { porTienda: {}, fecha: '' },
  };
}
function accesoDesdeFilaApp(f) {
  return { id: f.id, cedula: f.cedula, trabajadorId: f.trabajador_id || '', solicitudId: f.solicitud_id || '', tipo: f.tipo || 'PROMOCION', apellidos: f.apellidos || '', tiendaId: f.tienda_id, nombre: f.nombre, cargoDestinoId: f.cargo_destino, bateria: f.bateria || [], estado: f.estado, respuestas: f.respuestas || {}, ev: f.ev || {}, nivelEducativo: f.nivel_educativo || '', inicio: f.inicio || '', fin: f.fin || '', creado: f.creado, creadoPor: f.creado_por || '', expira: f.expira };
}
function perfilAUsuario(p) {
  return { id: p.id, nombre: p.nombre || p.correo, correo: p.correo, rol: p.rol, marca: p.marca || '', tiendaId: p.tienda_id || '', activo: p.activo, debeCambiarClave: p.debe_cambiar_clave };
}
function construirDatosNube(r) {
  const porCol = {};
  COLECCIONES_NUBE.forEach((c) => { porCol[c] = []; });
  r.registros.forEach((x) => { (porCol[x.coleccion] = porCol[x.coleccion] || []).push(x.data); });
  const aj = {}; r.ajustes.forEach((a) => { aj[a.clave] = a.data; });
  const def = ajustesPorDefecto();
  return {
    version: VERSION_DATOS,
    config: { ...def.config, ...(aj.config || {}) },
    plantillas: { ...def.plantillas, ...(aj.plantillas || {}) },
    hcNecesario: aj.hcNecesario || def.hcNecesario,
    montosApoyo: aj.montosApoyo || def.montosApoyo,
    pruebas: aj.pruebas || def.pruebas,
    pruebasTraslado: aj.pruebasTraslado || def.pruebasTraslado,
    plantillasOnboarding: aj.plantillasOnboarding || def.plantillasOnboarding,
    ipvPreguntas: Array.isArray(aj.ipvPreguntas) && aj.ipvPreguntas.length === IPV_TOTAL_PREGUNTAS ? aj.ipvPreguntas : def.ipvPreguntas,
    cumplimientoDiscapacidad: aj.cumplimientoDiscapacidad || def.cumplimientoDiscapacidad,
    accesosPrueba: (r.accesos || []).map(accesoDesdeFilaApp),
    ...porCol,
    bitacora: [...r.bitacora].sort((a, b) => (a.fecha < b.fecha ? 1 : -1)),
    remuneraciones: (r.remuneraciones || []).map((x) => x.data),
    documentosEmitidos: (r.emitidos || []).map((x) => x.data),
    usuarios: r.perfiles.map(perfilAUsuario),
    fichas: r.fichas.map((f) => { const sens = (r.sensibles || []).find((x) => x.cedula === f.cedula); return { ...f.data, ...(sens ? { discapacidad: sens.data } : {}), id: f.cedula, cedula: f.cedula, trabajadorId: f.trabajador_id || '', tiendaId: f.tienda_id || '' }; }),
  };
}
function tiendaRegistro(col, x, d) {
  if (col === 'tiendas') return x.id;
  if (['cargos', 'modelosCompensacion', 'bitacora'].includes(col)) return null;
  if (col === 'solicitudes') return tiendaDeSolicitud(x, d) || null;
  if (['documentos', 'resultadosPruebas', 'amonestaciones', 'evaluaciones'].includes(col)) { const tr = d.trabajadores.find((y) => y.id === x.trabajadorId); return tr ? tr.tiendaId : (x.tiendaId || null); }
  return x.tiendaId || null;
}
/* Quiénes tienen la solicitud pendiente por aprobar en su paso actual (sin el Administrador, que actúa como respaldo, ni quien la creó) */
function aprobadoresPendientes(datos, s) {
  if (!s || !['PENDIENTE', 'EN_REVISION'].includes(s.estado)) return [];
  if (s.modo !== 'QUORUM') { const pc = pasoActualDe(s); if (!pc || pc.tipo === 'CALIBRACION') return []; }
  const tiendaId = tiendaDeSolicitud(s, datos);
  const marcaDeTienda = {};
  (datos.tiendas || []).forEach((x) => { marcaDeTienda[x.id] = x.marca; });
  return (datos.usuarios || []).filter((u) => {
    if (u.activo === false || u.rol === 'admin' || u.id === s.creadaPor) return false;
    const uu = { ...u, marca: u.marca || marcaDeTienda[u.tiendaId] || '', marcaDeTienda };
    if (indicePasoPara(uu, s) < 0) return false;
    return !tiendaId || enAlcance(uu, tiendaId);
  }).map((u) => u.id);
}
/* Solicitudes nuevas o que avanzaron a un paso que espera aprobación, por una acción de la persona en sesión */
function solicitudesPorAprobar(antes, despues, usuarioId) {
  if (!antes || !despues || !usuarioId) return [];
  const previas = new Map((antes.solicitudes || []).map((x) => [x.id, x]));
  return (despues.solicitudes || []).filter((x) => {
    const p = previas.get(x.id);
    if (p === x || !['PENDIENTE', 'EN_REVISION'].includes(x.estado)) return false;
    const ev = (x.eventos || [])[(x.eventos || []).length - 1];
    if (!ev || ev.usuarioId !== usuarioId) return false;
    if (!p || p.estado === 'DEVUELTA') return true;
    return x.modo === 'QUORUM' ? p.faseFinal !== x.faseFinal : p.pasoActual !== x.pasoActual;
  }).map((x) => x.id);
}
/* Avisos por correo que genera un cambio: decisiones (al solicitante) y pendientes (a los aprobadores del paso) */
function avisosSolicitudes(antes, despues, usuarioId) {
  const avisos = solicitudesDecididas(antes, despues, usuarioId).map((solicitudId) => ({ solicitudId, clase: 'DECISION' }));
  solicitudesPorAprobar(antes, despues, usuarioId).forEach((solicitudId) => {
    const destinatarios = aprobadoresPendientes(despues, despues.solicitudes.find((x) => x.id === solicitudId));
    if (destinatarios.length) avisos.push({ solicitudId, clase: 'PENDIENTE', destinatarios });
  });
  return avisos;
}
/* Solicitudes que la persona en sesión acaba de APROBAR (aprobación final) o RECHAZAR; el cierre automático por egreso no cuenta */
const ESTADOS_DECISION = ['APROBADA', 'EJECUTADA', 'RECHAZADA'];
function solicitudesDecididas(antes, despues, usuarioId) {
  if (!antes || !despues || !usuarioId) return [];
  const previas = new Map((antes.solicitudes || []).map((x) => [x.id, x]));
  return (despues.solicitudes || []).filter((x) => {
    const p = previas.get(x.id);
    if (!p || p === x || !ESTADOS_DECISION.includes(x.estado) || ESTADOS_DECISION.includes(p.estado) || x.cerradaPorEgreso) return false;
    const ev = (x.eventos || [])[(x.eventos || []).length - 1];
    return Boolean(ev) && ESTADOS_DECISION.includes(ev.accion) && ev.usuarioId === usuarioId;
  }).map((x) => x.id);
}
function diferenciasNube(a, b) {
  const registros = []; const borrados = []; const ajustes = []; const fichas = []; const sensibles = []; const remuneraciones = []; const emisiones = [];
  COLECCIONES_NUBE.forEach((col) => {
    const xa = a[col] || []; const xb = b[col] || [];
    if (xa === xb) return;
    const mapa = new Map(xa.map((x) => [x.id, x]));
    xb.forEach((x) => { if (mapa.get(x.id) !== x) registros.push({ coleccion: col, id: String(x.id), tienda_id: tiendaRegistro(col, x, b), data: x }); });
    if (col !== 'bitacora') { const ids = new Set(xb.map((x) => x.id)); xa.forEach((x) => { if (!ids.has(x.id)) borrados.push({ coleccion: col, id: String(x.id) }); }); }
  });
  /* Si un trabajador cambia de tienda, sus registros (documentos, evaluaciones, solicitudes, etc.) pasan a la tienda destino y dejan de verse en la de origen */
  const tiendaAntes = new Map((a.trabajadores || []).map((x) => [x.id, x.tiendaId]));
  const movidos = new Set((b.trabajadores || []).filter((x) => tiendaAntes.has(x.id) && tiendaAntes.get(x.id) !== x.tiendaId).map((x) => x.id));
  if (movidos.size) {
    const ya = new Set(registros.map((r) => `${r.coleccion}|${r.id}`));
    ['documentos', 'resultadosPruebas', 'amonestaciones', 'evaluaciones', 'solicitudes', 'participaciones'].forEach((col) => {
      (b[col] || []).forEach((x) => {
        if (!movidos.has(x.trabajadorId) || x.tiendaId && col === 'solicitudes' || ya.has(`${col}|${x.id}`)) return;
        registros.push({ coleccion: col, id: String(x.id), tienda_id: tiendaRegistro(col, x, b), data: x });
      });
    });
  }
  AJUSTES_NUBE.forEach((k) => { if (a[k] !== b[k] && b[k] !== undefined) ajustes.push({ clave: k, data: b[k] }); });
  if ((a.fichas || []) !== (b.fichas || [])) {
    const mapa = new Map((a.fichas || []).map((x) => [x.id, x]));
    (b.fichas || []).forEach((f) => {
      if (mapa.get(f.id) === f) return;
      const { discapacidad, ...publica } = f; /* lo sensible va aparte */
      fichas.push({ cedula: f.id, trabajador_id: f.trabajadorId || null, tienda_id: f.tiendaId || null, data: publica, fuente: f.fuente || null });
      if (discapacidad) sensibles.push({ cedula: f.id, data: discapacidad });
    });
  }
  if ((a.remuneraciones || []) !== (b.remuneraciones || [])) {
    const mapaR = new Map((a.remuneraciones || []).map((x) => [x.id, x]));
    (b.remuneraciones || []).forEach((x) => { if (mapaR.get(x.id) !== x) remuneraciones.push({ id: x.id, trabajador_id: x.trabajadorId, cedula: x.cedula || null, tienda_id: x.tiendaId || null, marca: x.marca || null, visible_para: x.visiblePara || visiblePara(x.jefeRol), data: x }); });
  }
  if ((a.documentosEmitidos || []) !== (b.documentosEmitidos || [])) {
    const mapaE = new Map((a.documentosEmitidos || []).map((x) => [x.id, x]));
    (b.documentosEmitidos || []).forEach((x) => { if (mapaE.get(x.id) !== x) emisiones.push({ codigo: x.codigo, tipo: x.tipo || null, nombre: x.nombre || null, fecha: x.fecha || null, emisor_id: x.emisorId || null, emisor_nombre: x.emisorNombre || null, emisor_rol: x.emisorRol || null, marca: x.marca || null, huella: x.huella || null, anulado: Boolean(x.anulado), data: x }); });
  }
  return { registros, borrados, ajustes, fichas, sensibles, remuneraciones, emisiones, total: registros.length + borrados.length + ajustes.length + fichas.length + sensibles.length + remuneraciones.length + emisiones.length };
}

if (typeof window !== 'undefined' && window.__EXPONER_PRUEBAS__) window.__pruebas = { montoPernocta, montoApoyoPredeterminado, montoApoyo, pernoctaMontoPendiente, reglaMonto, diferenciasNube, solicitudesDecididas, solicitudesPorAprobar, aprobadoresPendientes, avisosSolicitudes, tiendaRegistro, reducer, conRequisiciones };

function MarcoAcceso({ titulo, subtitulo, children }) {
  return (
    <main className={`flex min-h-full items-center justify-center ${UI.fondo} px-4 py-10`}>
      <div className="w-full max-w-md">
        <LogoMarca marca="TODAS" alto={26} />
        <h1 className={`mt-2 text-2xl font-semibold tracking-tight ${UI.tinta}`} style={{ fontFamily: "'Fraunces', Georgia, serif" }}>{titulo}</h1>
        {subtitulo ? <p className={`mt-2 text-sm ${UI.tenue}`}>{subtitulo}</p> : null}
        <div className={`mt-6 rounded-xl border ${UI.borde} bg-white p-5 shadow-sm`}>{children}</div>
      </div>
    </main>
  );
}

function LoginNube() {
  const [modo, setModo] = useState('entrar');
  const [f, setF] = useState({ correo: '', clave: '', clave2: '', nombre: '' });
  const [error, setError] = useState('');
  const [ocupado, setOcupado] = useState(false);
  const [aviso, setAviso] = useState('');
  const cambia = (k) => (e) => setF((x) => ({ ...x, [k]: e.target.value }));
  const entrar = async (e) => {
    e.preventDefault(); setError('');
    if (!f.correo.trim() || !f.clave) { setError('Indique su correo y contraseña.'); return; }
    setOcupado(true);
    try { await NUBE.entrar(f.correo, f.clave); } catch (err) { setError(err.message); setOcupado(false); }
  };
  const activar = async (e) => {
    e.preventDefault(); setError('');
    if (f.nombre.trim().length < 3) { setError('Indique su nombre.'); return; }
    if (f.clave.length < 8) { setError('La contraseña debe tener al menos 8 caracteres.'); return; }
    if (f.clave !== f.clave2) { setError('Las contraseñas no coinciden.'); return; }
    setOcupado(true);
    try {
      await NUBE.gestionUsuarios({ accion: 'admin_inicial', correo: f.correo, clave: f.clave, nombre: f.nombre.trim() });
      setAviso('Cuenta de administrador activada. Entrando…');
      await NUBE.entrar(f.correo, f.clave);
    } catch (err) { setError(err.message); setOcupado(false); }
  };
  if (modo === 'olvido') return <OlvidoClave correoInicial={f.correo} onVolver={(msg) => { setModo('entrar'); setAviso(msg || ''); setError(''); }} />;
  return (
    <MarcoAcceso titulo="Sistema de Gestión Integrado de RRHH" subtitulo={modo === 'entrar' ? 'Inicie sesión con el correo y la contraseña que le asignó el Administrador.' : 'Activación única de la cuenta del Administrador inicial.'}>
      <form onSubmit={modo === 'entrar' ? entrar : activar} className="flex flex-col gap-3">
        {modo === 'admin' ? <Campo etiqueta="Nombre y apellido" htmlFor="ln-nombre" requerido><input id="ln-nombre" className={UI.input} value={f.nombre} onChange={cambia('nombre')} autoComplete="name" /></Campo> : null}
        <Campo etiqueta="Correo" htmlFor="ln-correo" requerido><input id="ln-correo" type="email" className={UI.input} value={f.correo} onChange={cambia('correo')} autoComplete="username" /></Campo>
        <Campo etiqueta="Contraseña" htmlFor="ln-clave" requerido><input id="ln-clave" type="password" className={UI.input} value={f.clave} onChange={cambia('clave')} autoComplete={modo === 'entrar' ? 'current-password' : 'new-password'} /></Campo>
        {modo === 'admin' ? <Campo etiqueta="Repita la contraseña" htmlFor="ln-clave2" requerido><input id="ln-clave2" type="password" className={UI.input} value={f.clave2} onChange={cambia('clave2')} autoComplete="new-password" /></Campo> : null}
        {error ? <p className="text-sm text-[#B42318]" role="alert">{error}</p> : null}
        {aviso ? <p className="text-sm text-emerald-800">{aviso}</p> : null}
        <Boton type="submit" disabled={ocupado} icono={ocupado ? Loader2 : Lock}>{modo === 'entrar' ? 'Entrar' : 'Activar y entrar'}</Boton>
      </form>
      <div className={`mt-4 border-t ${UI.borde} pt-3 text-xs ${UI.tenue}`}>
        {modo === 'entrar'
          ? <><button type="button" id="ln-olvido" className={`${UI.primarioTxt} hover:underline`} onClick={() => { setModo('olvido'); setError(''); setAviso(''); }}>¿Olvidó su contraseña?</button> · <button type="button" className={`${UI.primarioTxt} hover:underline`} onClick={() => { setModo('admin'); setError(''); }}>Primer acceso del Administrador</button></>
          : <button type="button" className={`${UI.primarioTxt} hover:underline`} onClick={() => { setModo('entrar'); setError(''); }}>Volver a iniciar sesión</button>}
      </div>
      <div className="mt-4"><TarjetaPortal /></div>
      <div className="mt-3 text-center"><EnlaceVerificar /></div>
      <div className="mt-3 text-center"><InsigniaVersion /></div>
    </MarcoAcceso>
  );
}

/* Preguntas de seguridad para restablecer la contraseña (v1.16.0). Las respuestas se guardan solo como hash en el servidor. */
const PREGUNTAS_SEGURIDAD = [
  { id: 'q01', texto: '¿En qué ciudad nació su madre?' },
  { id: 'q02', texto: '¿Cómo se llamaba su primera mascota?' },
  { id: 'q03', texto: '¿Cuál es el segundo apellido de su abuela materna?' },
  { id: 'q04', texto: '¿Cómo se llamaba su escuela primaria?' },
  { id: 'q05', texto: '¿Cuál era su apodo de la infancia?' },
  { id: 'q06', texto: '¿Cuál fue su primer empleo?' },
  { id: 'q07', texto: '¿En qué calle vivió de niño o niña?' },
  { id: 'q08', texto: '¿Cómo se llama su mejor amigo o amiga de la infancia?' },
  { id: 'q09', texto: '¿Cuál era su comida favorita de la infancia?' },
  { id: 'q10', texto: '¿Cómo se llamaba su primer jefe o jefa?' },
];
const textoPregunta = (id) => (PREGUNTAS_SEGURIDAD.find((x) => x.id === id) || { texto: id }).texto;
function validarPreguntas(ps) {
  if (ps.some((x) => !x.id)) return 'Elija las tres preguntas de seguridad.';
  if (new Set(ps.map((x) => x.id)).size !== 3) return 'Elija tres preguntas distintas.';
  if (ps.some((x) => normalizarClave(x.respuesta).length < 3)) return 'Cada respuesta debe tener al menos 3 letras o números.';
  return '';
}
function CamposPreguntas({ valor, onCambiar }) {
  const poner = (i, k, v) => onCambiar(valor.map((x, j) => (j === i ? { ...x, [k]: v } : x)));
  return (
    <fieldset className={`rounded-lg border ${UI.borde} p-3`}>
      <legend className={`px-1 text-sm font-semibold ${UI.tinta}`}>Preguntas de seguridad</legend>
      <p className={`mb-2 text-xs ${UI.tenue}`}>Le permitirán crear una contraseña nueva si la olvida. Elija respuestas que solo usted conozca; no distingue mayúsculas ni tildes.</p>
      {valor.map((x, i) => (
        <div key={i} className="mb-2 grid gap-2 sm:grid-cols-2">
          <Campo etiqueta={`Pregunta ${i + 1}`} htmlFor={`ps-p${i + 1}`}><select id={`ps-p${i + 1}`} className={UI.input} value={x.id} onChange={(e) => poner(i, 'id', e.target.value)}><option value="">Seleccione…</option>{PREGUNTAS_SEGURIDAD.map((q) => <option key={q.id} value={q.id}>{q.texto}</option>)}</select></Campo>
          <Campo etiqueta={`Respuesta ${i + 1}`} htmlFor={`ps-r${i + 1}`}><input id={`ps-r${i + 1}`} type="password" autoComplete="off" className={UI.input} value={x.respuesta} onChange={(e) => poner(i, 'respuesta', e.target.value)} /></Campo>
        </div>
      ))}
    </fieldset>
  );
}
const PREGUNTAS_VACIAS = () => [0, 1, 2].map(() => ({ id: '', respuesta: '' }));

function FormCambioClave({ onListo, textoBoton = 'Guardar contraseña', conPreguntas = false }) {
  const [f, setF] = useState({ clave: '', clave2: '' });
  const [ps, setPs] = useState(PREGUNTAS_VACIAS);
  const [error, setError] = useState('');
  const [ocupado, setOcupado] = useState(false);
  const guardar = async (e) => {
    e.preventDefault(); setError('');
    if (f.clave.length < 8) { setError('La contraseña debe tener al menos 8 caracteres.'); return; }
    if (!/[A-Za-z]/.test(f.clave) || !/\d/.test(f.clave)) { setError('Use letras y números.'); return; }
    if (f.clave !== f.clave2) { setError('Las contraseñas no coinciden.'); return; }
    if (conPreguntas) { const m = validarPreguntas(ps); if (m) { setError(m); return; } }
    setOcupado(true);
    try { await NUBE.cambiarClave(f.clave); if (conPreguntas) { try { await NUBE.guardarPreguntas(ps); } catch (e2) { if (!e2.noActivada) throw e2; } } onListo(); } catch (err) { setError(err.message); setOcupado(false); }
  };
  return (
    <form onSubmit={guardar} className="flex flex-col gap-3">
      <Campo etiqueta="Nueva contraseña" htmlFor="cc-clave" ayuda="Mínimo 8 caracteres, con letras y números." requerido><input id="cc-clave" type="password" className={UI.input} value={f.clave} onChange={(e) => setF((x) => ({ ...x, clave: e.target.value }))} autoComplete="new-password" /></Campo>
      <Campo etiqueta="Repita la contraseña" htmlFor="cc-clave2" requerido><input id="cc-clave2" type="password" className={UI.input} value={f.clave2} onChange={(e) => setF((x) => ({ ...x, clave2: e.target.value }))} autoComplete="new-password" /></Campo>
      {conPreguntas ? <CamposPreguntas valor={ps} onCambiar={setPs} /> : null}
      {error ? <p className="text-sm text-[#B42318]" role="alert">{error}</p> : null}
      <Boton type="submit" disabled={ocupado} icono={ocupado ? Loader2 : Save}>{textoBoton}</Boton>
    </form>
  );
}

function FormPreguntasSeguridad({ onListo }) {
  const [ps, setPs] = useState(PREGUNTAS_VACIAS);
  const [error, setError] = useState('');
  const [ocupado, setOcupado] = useState(false);
  const guardar = async (e) => {
    e.preventDefault(); setError('');
    const m = validarPreguntas(ps); if (m) { setError(m); return; }
    setOcupado(true);
    try { await NUBE.guardarPreguntas(ps); onListo(); } catch (err) { setError(err.message); setOcupado(false); }
  };
  return (
    <form onSubmit={guardar} className="flex flex-col gap-3">
      <CamposPreguntas valor={ps} onCambiar={setPs} />
      {error ? <p className="text-sm text-[#B42318]" role="alert">{error}</p> : null}
      <Boton type="submit" disabled={ocupado} icono={ocupado ? Loader2 : Save}>Guardar preguntas</Boton>
    </form>
  );
}

/* Restablecer la contraseña sin el Administrador: correo → preguntas → respuestas y contraseña nueva */
function OlvidoClave({ correoInicial, onVolver }) {
  const [correo, setCorreo] = useState(correoInicial || '');
  const [preg, setPreg] = useState(null);
  const [resp, setResp] = useState(['', '', '']);
  const [f, setF] = useState({ clave: '', clave2: '' });
  const [error, setError] = useState('');
  const [ocupado, setOcupado] = useState(false);
  const buscar = async (e) => {
    e.preventDefault(); setError('');
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(correo.trim())) { setError('Indique su correo.'); return; }
    setOcupado(true);
    try { setPreg(await NUBE.preguntasDeCorreo(correo.trim().toLowerCase())); } catch (err) { setError(err.message); }
    setOcupado(false);
  };
  const restablecer = async (e) => {
    e.preventDefault(); setError('');
    if (resp.some((x) => normalizarClave(x).length < 1)) { setError('Responda las tres preguntas.'); return; }
    if (f.clave.length < 8 || !/[A-Za-z]/.test(f.clave) || !/\d/.test(f.clave)) { setError('La contraseña debe tener al menos 8 caracteres, con letras y números.'); return; }
    if (f.clave !== f.clave2) { setError('Las contraseñas no coinciden.'); return; }
    setOcupado(true);
    try { await NUBE.restablecerClave(correo.trim().toLowerCase(), resp, f.clave); onVolver('Contraseña restablecida. Ya puede iniciar sesión con la nueva.'); } catch (err) { setError(err.message); setOcupado(false); }
  };
  return (
    <MarcoAcceso titulo="Restablecer contraseña" subtitulo={preg ? 'Responda sus preguntas de seguridad y cree una contraseña nueva.' : 'Indique su correo para ver sus preguntas de seguridad.'}>
      {!preg ? (
        <form onSubmit={buscar} className="flex flex-col gap-3">
          <Campo etiqueta="Correo" htmlFor="ol-correo" requerido><input id="ol-correo" type="email" className={UI.input} value={correo} onChange={(e) => setCorreo(e.target.value)} autoComplete="username" /></Campo>
          {error ? <p className="text-sm text-[#B42318]" role="alert">{error}</p> : null}
          <Boton type="submit" disabled={ocupado} icono={ocupado ? Loader2 : ArrowRightLeft}>Continuar</Boton>
        </form>
      ) : (
        <form onSubmit={restablecer} className="flex flex-col gap-3">
          {preg.map((id, i) => <Campo key={i} etiqueta={textoPregunta(id)} htmlFor={`ol-r${i + 1}`} requerido><input id={`ol-r${i + 1}`} type="password" autoComplete="off" className={UI.input} value={resp[i]} onChange={(e) => setResp((r) => r.map((x, j) => (j === i ? e.target.value : x)))} /></Campo>)}
          <Campo etiqueta="Nueva contraseña" htmlFor="ol-clave" ayuda="Mínimo 8 caracteres, con letras y números." requerido><input id="ol-clave" type="password" className={UI.input} value={f.clave} onChange={(e) => setF((x) => ({ ...x, clave: e.target.value }))} autoComplete="new-password" /></Campo>
          <Campo etiqueta="Repita la contraseña" htmlFor="ol-clave2" requerido><input id="ol-clave2" type="password" className={UI.input} value={f.clave2} onChange={(e) => setF((x) => ({ ...x, clave2: e.target.value }))} autoComplete="new-password" /></Campo>
          {error ? <p className="text-sm text-[#B42318]" role="alert">{error}</p> : null}
          <Boton type="submit" disabled={ocupado} icono={ocupado ? Loader2 : Lock}>Restablecer contraseña</Boton>
          <p className={`m-0 text-xs ${UI.tenue}`}>Tras 5 intentos fallidos se bloquea el restablecimiento por 30 minutos y el Administrador lo ve en «Usuarios y accesos». Si no configuró sus preguntas, pida al Administrador que restablezca su contraseña.</p>
        </form>
      )}
      <div className={`mt-4 border-t ${UI.borde} pt-3 text-xs`}><button type="button" className={`${UI.primarioTxt} hover:underline`} onClick={() => onVolver('')}>Volver a iniciar sesión</button></div>
    </MarcoAcceso>
  );
}

function PantallaNube() {
  const { estado, nube } = useApp();
  const n = estado.nube;
  if (n.estado === 'sin_sesion') return <LoginNube />;
  if (n.estado === 'pendiente') {
    return (
      <MarcoAcceso titulo="Cuenta pendiente de activación" subtitulo={`La cuenta ${n.perfil ? n.perfil.correo : ''} aún no tiene un rol asignado o está inactiva.`}>
        <p className={`text-sm ${UI.tinta}`}>Pida al Administrador del sistema que le asigne su rol, marca y tienda.</p>
        <Boton variante="secundario" className="mt-4" icono={LogOut} onClick={() => NUBE.salir()}>Salir</Boton>
      </MarcoAcceso>
    );
  }
  if (n.estado === 'error') {
    return (
      <MarcoAcceso titulo="No se pudieron cargar los datos" subtitulo={n.mensaje}>
        <div className="flex gap-2"><Boton icono={RotateCcw} onClick={() => window.location.reload()}>Reintentar</Boton><Boton variante="secundario" icono={LogOut} onClick={() => NUBE.salir()}>Salir</Boton></div>
      </MarcoAcceso>
    );
  }
  if (n.estado === 'cambiar_clave') {
    return (
      <MarcoAcceso titulo="Cree su contraseña personal" subtitulo="Por seguridad, reemplace la contraseña temporal que le entregó el Administrador y defina sus preguntas de seguridad.">
        <FormCambioClave conPreguntas onListo={() => nube.recargar()} textoBoton="Guardar y continuar" />
      </MarcoAcceso>
    );
  }
  return <div className={`flex min-h-full items-center justify-center ${UI.fondo}`}><Cargando texto={n.estado === 'cargando' ? 'Cargando datos…' : 'Verificando sesión…'} /></div>;
}

/* ---------- Usuarios y accesos (solo versión en la nube, Administrador) ---------- */
function claveTemporal() {
  const letras = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ'; const nums = '23456789';
  const azar = (s) => s[Math.floor(Math.random() * s.length)];
  return `${Array.from({ length: 6 }, () => azar(letras)).join('')}${azar(nums)}${azar(nums)}`;
}
function RegistroRestablecimientos() {
  const [abierto, setAbierto] = useState(false);
  const [filas, setFilas] = useState(null);
  const [error, setError] = useState('');
  const cargar = () => { setError(''); NUBE.registroRestablecimientos().then(setFilas).catch((e) => setError(e.message)); };
  const ETQ = { OK: ['Restablecida', 'exito'], FALLIDO: ['Respuestas incorrectas', 'alerta'], BLOQUEO_30_MIN: ['Bloqueada 30 min', 'peligro'], BLOQUEADO: ['Intento durante el bloqueo', 'peligro'] };
  return (
    <div className="mt-4">
      <Boton tamano="sm" variante="secundario" id="us-reg-rest" icono={History} onClick={() => { const v = !abierto; setAbierto(v); if (v) cargar(); }}>{abierto ? 'Ocultar restablecimientos de clave' : 'Ver restablecimientos de clave'}</Boton>
      {abierto ? (
        <div className="mt-2">
          {error ? <p className="text-sm text-[#B42318]" role="alert">{error}</p> : null}
          <Tabla filas={(filas || []).map((r) => ({ ...r, id: String(r.id) }))} vacio={<EstadoVacio icono={CheckCircle2} titulo="Sin restablecimientos registrados" />} columnas={[
            { clave: 'momento', titulo: 'Fecha y hora', clase: 'tabular-nums whitespace-nowrap', render: (r) => new Date(r.momento).toLocaleString('es-VE') },
            { clave: 'correo', titulo: 'Correo', clase: 'font-mono text-xs' },
            { clave: 'resultado', titulo: 'Resultado', render: (r) => { const t = ETQ[r.resultado] || [r.resultado, 'neutro']; return <Badge tono={t[1]}>{t[0]}</Badge>; } },
          ]} />
        </div>
      ) : null}
    </div>
  );
}

function GestionUsuarios() {
  const { datos, usuario, nombreTienda, nube, dispatch } = useApp();
  const toast = useToast();
  const [form, setForm] = useState(null);
  const [error, setError] = useState('');
  const [ocupado, setOcupado] = useState(false);
  const [entrega, setEntrega] = useState(null);
  const [busca, setBusca] = useState('');
  if (usuario.rol !== 'admin') return <EstadoVacio icono={Lock} titulo="Sin acceso" />;
  const usuarios = [...datos.usuarios].filter((u) => !busca || `${u.nombre} ${u.correo} ${nombreTienda(u.tiendaId)}`.toLowerCase().includes(busca.toLowerCase())).sort((a, b) => a.rol.localeCompare(b.rol) || a.nombre.localeCompare(b.nombre));
  const tiendas = [...datos.tiendas].sort((a, b) => a.marca.localeCompare(b.marca) || a.nombre.localeCompare(b.nombre));
  const abrir = (u) => { setError(''); setForm(u ? { id: u.id, pendiente: u.rol === 'pendiente', nombre: u.nombre, correo: u.correo, rol: u.rol, marca: u.marca, tiendaId: u.tiendaId, activo: u.activo !== false } : { id: '', nombre: '', correo: '', rol: 'tienda', marca: '', tiendaId: '', activo: true, clave: claveTemporal() }); };
  const guardar = async () => {
    setError('');
    if (form.nombre.trim().length < 3) { setError('Indique el nombre.'); return; }
    if (!form.id && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.correo.trim())) { setError('Indique un correo válido.'); return; }
    if (['marca', 'operaciones', 'visor', 'consulta'].includes(form.rol) && !form.marca) { setError('Indique la marca.'); return; }
    if (form.rol === 'tienda' && !form.tiendaId) { setError('Indique la tienda.'); return; }
    if (!NUBE) {
      const correo = form.correo.trim().toLowerCase();
      if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(correo)) { setError('Indique un correo válido.'); return; }
      if (datos.usuarios.some((u) => u.id !== form.id && String(u.correo || '').toLowerCase() === correo)) { setError('Ese correo ya está asignado a otro usuario.'); return; }
      const marcaU = ['marca', 'operaciones', 'visor', 'consulta'].includes(form.rol) ? form.marca : (form.rol === 'tienda' ? (datos.tiendas.find((x) => x.id === form.tiendaId) || {}).marca || '' : '');
      const id = form.id || `${form.rol}.${correo.split('@')[0].replace(/[^a-z0-9]+/g, '.')}`;
      dispatch({ type: 'GUARDAR_USUARIO', payload: { usuario: { id, nombre: form.nombre.trim(), correo, rol: form.rol, marca: marcaU, tiendaId: form.rol === 'tienda' ? form.tiendaId : '', activo: form.activo }, bitacora: { usuarioId: usuario.id, accion: form.id ? 'EDITAR_USUARIO' : 'CREAR_USUARIO', entidad: 'usuario', entidadId: id, detalle: `${form.nombre.trim()} · ${correo}` } } });
      toast(form.id ? 'Usuario actualizado.' : 'Usuario creado.');
      setForm(null);
      return;
    }
    setOcupado(true);
    try {
      const cuerpo = { nombre: form.nombre.trim(), rol: form.rol, marca: ['marca', 'operaciones', 'visor', 'consulta'].includes(form.rol) ? form.marca : (form.rol === 'tienda' ? (datos.tiendas.find((x) => x.id === form.tiendaId) || {}).marca || null : null), tiendaId: form.rol === 'tienda' ? form.tiendaId : null };
      if (form.id) await NUBE.gestionUsuarios({ accion: 'actualizar', id: form.id, activo: form.activo, ...cuerpo });
      else { await NUBE.gestionUsuarios({ accion: 'crear', correo: form.correo.trim(), clave: form.clave, ...cuerpo }); setEntrega({ correo: form.correo.trim().toLowerCase(), clave: form.clave }); }
      toast(form.id ? 'Usuario actualizado.' : 'Usuario creado.');
      setForm(null);
      await nube.recargar();
    } catch (e) { setError(e.message); }
    setOcupado(false);
  };
  const restablecer = async (u) => {
    const clave = claveTemporal();
    try { await NUBE.gestionUsuarios({ accion: 'restablecer', id: u.id, clave }); setEntrega({ correo: u.correo, clave }); toast('Contraseña restablecida.'); await nube.recargar(); } catch (e) { toast(e.message, 'error'); }
  };
  const copiar = async (texto) => { try { await navigator.clipboard.writeText(texto); toast('Copiado.'); } catch (e) { toast('Seleccione y copie el texto manualmente.', 'error'); } };
  return (
    <div>
      <Encabezado titulo="Usuarios y accesos" subtitulo={`Cada persona entra con su correo y contraseña, y a ese correo le llegan los recordatorios de su flujo. El rol define lo que ve: Gerente de Tienda (su tienda), Marca y Operaciones (su marca), RRHH, General y Administrador (todo).${NUBE ? '' : ' En esta versión de prueba no se usan contraseñas.'}`}
        acciones={<Boton icono={Plus} onClick={() => abrir(null)}>Nuevo usuario</Boton>} />
      {datos.usuarios.some((u) => !u.correo && u.activo !== false) ? <p className="mb-3 rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-900" role="status">{`${datos.usuarios.filter((u) => !u.correo && u.activo !== false).length} usuarios sin correo registrado: no recibirán recordatorios. Pulse Editar para registrarlo.`}</p> : null}
      <input id="us-busca" className={`${UI.input} mb-3 sm:max-w-xs`} placeholder="Buscar por nombre, correo o tienda" value={busca} onChange={(e) => setBusca(e.target.value)} aria-label="Buscar usuario" />
      <Tabla filas={usuarios} columnas={[
        { clave: 'nombre', titulo: 'Nombre' },
        { clave: 'correo', titulo: 'Correo', clase: 'font-mono text-xs', render: (u) => u.correo || <Badge tono="alerta">Sin correo</Badge> },
        { clave: 'rol', titulo: 'Rol', render: (u) => (u.rol === 'pendiente' ? <Badge tono="alerta">Pendiente</Badge> : ROLES[u.rol]) },
        { clave: 'alcance', titulo: 'Alcance', render: (u) => (u.rol === 'tienda' ? nombreTienda(u.tiendaId) : ['marca', 'operaciones', 'visor', 'consulta'].includes(u.rol) ? MARCAS[u.marca] || '—' : 'Balú y Planeta') },
        { clave: 'estado', titulo: 'Estado', render: (u) => (u.activo === false ? <Badge tono="peligro">Inactivo</Badge> : u.debeCambiarClave ? <Badge tono="info">Clave temporal</Badge> : <Badge tono="exito">Activo</Badge>) },
        { clave: 'acc', titulo: '', render: (u) => <div className="flex gap-1"><Boton tamano="sm" variante="secundario" icono={Pencil} onClick={() => abrir(u)}>Editar</Boton>{NUBE ? <Boton tamano="sm" variante="fantasma" icono={RotateCcw} onClick={() => restablecer(u)}>Clave</Boton> : null}</div> },
      ]} />
      {NUBE && NUBE.registroRestablecimientos ? <RegistroRestablecimientos /> : null}
      <Modal abierto={Boolean(form)} titulo={form && form.id ? 'Editar usuario' : 'Nuevo usuario'} onCerrar={() => setForm(null)}
        pie={<><Boton variante="secundario" onClick={() => setForm(null)}>Cancelar</Boton><Boton icono={ocupado ? Loader2 : Save} disabled={ocupado} onClick={guardar}>Guardar</Boton></>}>
        {form ? (
          <div className="flex flex-col gap-3">
            {form.id && !form.pendiente ? <p className="m-0 rounded-md border border-amber-200 bg-amber-50 p-2 text-xs text-amber-900">Un usuario no se reutiliza: si la persona cambia, cree un usuario nuevo y desactive este. Así el historial de aprobaciones conserva quién actuó.</p> : null}
            <Campo etiqueta="Nombre y apellido" htmlFor="us-nombre" requerido><input id="us-nombre" disabled={Boolean(form.id && !form.pendiente)} className={UI.input} value={form.nombre} onChange={(e) => setForm((x) => ({ ...x, nombre: e.target.value }))} /></Campo>
            <Campo etiqueta="Correo" htmlFor="us-correo" requerido><input id="us-correo" type="email" className={UI.input} value={form.correo || ''} disabled={Boolean(NUBE && form.id)} onChange={(e) => setForm((x) => ({ ...x, correo: e.target.value }))} /></Campo>
            <Campo etiqueta="Rol" htmlFor="us-rol" requerido>
              <select id="us-rol" disabled={Boolean(form.id && !form.pendiente)} className={UI.input} value={form.rol} onChange={(e) => setForm((x) => ({ ...x, rol: e.target.value }))}>
                {Object.keys(ROLES).map((k) => <option key={k} value={k}>{ROLES[k]}</option>)}
              </select>
            </Campo>
            {['marca', 'operaciones', 'visor', 'consulta'].includes(form.rol) ? (
              <Campo etiqueta="Marca" htmlFor="us-marca" requerido><select id="us-marca" disabled={Boolean(form.id && !form.pendiente)} className={UI.input} value={form.marca} onChange={(e) => setForm((x) => ({ ...x, marca: e.target.value }))}><option value="">Seleccione…</option>{Object.keys(MARCAS).map((k) => <option key={k} value={k}>{MARCAS[k]}</option>)}</select></Campo>
            ) : null}
            {form.rol === 'tienda' ? (
              <Campo etiqueta="Tienda" htmlFor="us-tienda" requerido><select id="us-tienda" disabled={Boolean(form.id && !form.pendiente)} className={UI.input} value={form.tiendaId} onChange={(e) => setForm((x) => ({ ...x, tiendaId: e.target.value }))}><option value="">Seleccione…</option>{tiendas.map((x) => <option key={x.id} value={x.id}>{MARCAS[x.marca]} · {x.nombre}</option>)}</select></Campo>
            ) : null}
            {form.id ? <label htmlFor="us-activo" className={`flex items-center gap-2 text-sm ${UI.tinta}`}><input id="us-activo" type="checkbox" className="h-4 w-4 accent-[#6B1E3F]" checked={form.activo} onChange={(e) => setForm((x) => ({ ...x, activo: e.target.checked }))} />Usuario activo</label>
              : NUBE ? <Dato etiqueta="Contraseña temporal" valor={form.clave} mono /> : null}
            {error ? <p className="text-sm text-[#B42318]" role="alert">{error}</p> : null}
          </div>
        ) : null}
      </Modal>
      <Modal abierto={Boolean(entrega)} titulo="Entregue estos datos al usuario" onCerrar={() => setEntrega(null)} pie={<Boton onClick={() => setEntrega(null)}>Listo</Boton>}>
        {entrega ? (
          <div className="flex flex-col gap-3">
            <Dato etiqueta="Correo" valor={entrega.correo} mono />
            <div className="flex items-end gap-2"><Dato etiqueta="Contraseña temporal" valor={entrega.clave} mono /><Boton tamano="sm" variante="secundario" icono={Copy} onClick={() => copiar(`Usuario: ${entrega.correo}\nContraseña temporal: ${entrega.clave}`)}>Copiar</Boton></div>
            <p className={`text-xs ${UI.tenue}`}>Al entrar por primera vez, el sistema le pedirá crear su propia contraseña. Esta contraseña temporal no se vuelve a mostrar.</p>
          </div>
        ) : null}
      </Modal>
    </div>
  );
}

/* ---------- Sincronización de datos de trabajadores ---------- */
function contratoDesdeIngreso(fechaIngreso, cargoId) {
  const cg = CARGOS_SEMILLA.find((c) => c.id === cargoId);
  if (cg && cg.administrativo) {
    const fin = sumarDias(fechaIngreso, 89);
    return fin < hoyISO() ? { tipo: 'INDETERMINADO', fechaFijo: sumarDias(fechaIngreso, 90), hitos: { PRUEBA_ADM: { estado: 'SUPERADO', fecha: sumarDias(fechaIngreso, 90), solicitudId: '', puntaje: null } } } : { tipo: 'DETERMINADO', fechaFijo: '', hitos: {}, pruebaHasta: fin };
  }
  return contratoSemilla(fechaIngreso, diffDias(fechaIngreso, hoyISO()), Boolean(cg && cg.esGerencial), []);
}
/* Lee un Excel/CSV y devuelve la matriz de cada hoja (el reporte de BI trae varias: estructura, Planeta, Balú). */
async function leerArchivoHojas(archivo) {
  const nombre = archivo.name.toLowerCase();
  const leer = (modo) => new Promise((ok, falla) => { const r = new FileReader(); r.onload = () => ok(r.result); r.onerror = () => falla(r.error || new Error('lectura fallida')); if (modo === 'texto') r.readAsText(archivo, 'utf-8'); else r.readAsArrayBuffer(archivo); });
  if (nombre.endsWith('.csv') || nombre.endsWith('.txt')) {
    const texto = await leer('texto');
    const sep = (texto.split('\n')[0].match(/;/g) || []).length > (texto.split('\n')[0].match(/,/g) || []).length ? ';' : texto.includes('\t') ? '\t' : ',';
    return [texto.replace(/^\ufeff/, '').split(/\r?\n/).map((l) => l.split(sep).map((c) => c.replace(/^"|"$/g, '').trim()))];
  }
  const XLSX = await cargarLibreria(SHEETJS_URL, 'XLSX');
  const libro = XLSX.read(await leer('buffer'), { type: 'array' });
  return libro.SheetNames.map((n) => XLSX.utils.sheet_to_json(libro.Sheets[n], { header: 1, raw: true, defval: '' }));
}

/* Igual que leerArchivoHojas pero conserva el nombre de cada hoja (solo libros de Excel) */
async function leerLibroNombres(archivo) {
  const leer = () => new Promise((ok, falla) => { const r = new FileReader(); r.onload = () => ok(r.result); r.onerror = () => falla(r.error || new Error('lectura fallida')); r.readAsArrayBuffer(archivo); });
  const XLSX = await cargarLibreria(SHEETJS_URL, 'XLSX');
  const libro = XLSX.read(await leer(), { type: 'array' });
  return libro.SheetNames.map((n) => ({ nombre: n, filas: XLSX.utils.sheet_to_json(libro.Sheets[n], { header: 1, raw: true, defval: '' }) }));
}

const NIVELES_INSTRUCCION = ['Primaria', 'Bachiller', 'Técnico Superior Universitario (TSU)', 'Universitario', 'Postgrado'];
/* Nivel de instrucción deducido del texto libre del formulario; vacío si no se puede deducir */
function nivelDesdeTitulo(t) {
  const n = String(t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (!n.trim()) return '';
  if (/postgrado|maestria|magister|doctor|especializacion/.test(n)) return 'Postgrado';
  if (/\btsu\b|tecnico superior/.test(n)) return 'Técnico Superior Universitario (TSU)';
  if (/licenciad|ingenier|abogad|contador|administrador|universitari|economista|arquitect|medic|psicolog|educador|profesor|\blic\b/.test(n)) return 'Universitario';
  if (/bachiller|media general|secundaria/.test(n)) return 'Bachiller';
  if (/primaria|basica/.test(n)) return 'Primaria';
  return '';
}
function trabajadorDesdeFicha(f, fechaIngreso, cargoId, tiendaId, datos) {
  const ti = datos.tiendas.find((x) => x.id === tiendaId);
  const cg = datos.cargos.find((x) => x.id === cargoId);
  const dias = diffDias(fechaIngreso, hoyISO());
  const t = {
    id: `W-${f.cedula}`, marca: ti ? ti.marca : f.marca, tiendaId, tiendaIngresoId: tiendaId, cargoId,
    nombres: f.nombres, apellidos: f.apellidos, cedula: `${f.letra || 'V'}-${f.cedula}`, fechaNacimiento: f.fechaNacimiento || '',
    fechaIngreso, fechaEgreso: '', motivoEgreso: '', estatus: 'ACTIVO', telefono: f.telefono || '', correo: f.correo || '', genero: f.genero || '', estadoCivil: (f.estadoCivil || '').replace(/\s*\(a\)/i, '/a'),
    direccion: [f.direccion && f.direccion.calle, f.direccion && f.direccion.sector, f.direccion && f.direccion.edificio, f.direccion && f.direccion.municipio, f.estadoResidencia].filter(Boolean).join(', '),
    datosBaseBloqueados: true,
    estadoResidencia: f.estadoResidencia || '', municipio: (f.direccion && f.direccion.municipio) || '', tieneHijos: textoHijos({}, f) === 'Con hijos' ? 'Sí' : textoHijos({}, f) === 'Sin hijos' ? 'No' : '',
    formacion: { nivel: nivelDesdeTitulo(f.educacion), titulo: f.educacion || '', complementaria: f.educacionComplementaria || '' },
    historial: [{ fecha: fechaIngreso, tipo: 'INGRESO', detalle: `Ingreso como ${cg ? cg.nombre : cargoId} en ${ti ? ti.nombre : tiendaId} (alta por sincronización de datos)` }],
    contrato: contratoDesdeIngreso(fechaIngreso, cargoId),
  };
  if (dias >= (Number(datos.config.diasConfirmarPermanencia) || 4)) t.permanencia = { estado: 'CONFIRMADO', fecha: hoyISO(), usuarioId: 'sincronizacion' };
  return t;
}

/* Lectura en vivo del repositorio (conector de Microsoft 365, solo al abrir el sistema desde Claude); se guarda en memoria para no releerlo en cada búsqueda */
const URI_SALIDAS = 'file:///b!m4ot4uE7ek6H0wERuz3n4cHWcLqjJv5EpqUgFKGeA3Az6b21vRNDTZTDT0IAUjTV/01KQWK7RUHT3QKE4JQ2RG36MKTCT5WSQKZ';
const NOMBRE_SALIDAS = 'Entrevista de Salida.xlsx';
/* Clasifica por tienda las entrevistas leídas: primero el expediente del trabajador (misma cédula); si no, el lugar indicado en la entrevista */
function filasSalidasClasificadas(filasBrutas, datos) {
  const porCed = new Map(datos.trabajadores.map((tr) => [soloDigitos(tr.cedula), tr]));
  const previas = new Map((datos.entrevistasSalida || []).map((x) => [x.id, x]));
  return filasBrutas.map((x) => {
    const tr = x.cedula ? porCed.get(x.cedula) : null;
    const prev = previas.get(x.id);
    return { ...x, trabajadorId: tr ? tr.id : '', tiendaId: (tr && tr.tiendaId) || x.tiendaId || (prev && prev.tiendaId) || '', cargoId: x.cargoId || (tr ? tr.cargoId : '') };
  });
}
const REPO_CACHE = { matriz: null, uri: '', hora: 0 };
async function leerMatrizRepositorio(repo, forzar = false) {
  if (!forzar && REPO_CACHE.matriz && REPO_CACHE.uri === repo.uri && Date.now() - REPO_CACHE.hora < 10 * 60 * 1000) return REPO_CACHE.matriz;
  const mcp = window.claude && window.claude.use ? await window.claude.use('mcp') : null;
  if (!mcp) throw new Error('La lectura directa solo está disponible al abrir el sistema desde Claude. Use «Cargar formulario» con el archivo descargado.');
  const r = await mcp.callTool('Microsoft 365', 'read_resource', { uri: repo.uri });
  const texto = typeof r.payload === 'string' ? r.payload : (r.content || []).map((b) => b.text || '').join('\n');
  const lineas = texto.split('\n');
  const ini = lineas.findIndex((x) => x.startsWith('Id\t'));
  if (ini < 0) throw new Error('No se reconoce el contenido del repositorio.');
  const matriz = [lineas[ini].split('\t')];
  lineas.slice(ini + 1).forEach((x) => { if (x.trim() && x.includes('\t')) matriz.push(x.split('\t')); });
  REPO_CACHE.matriz = matriz; REPO_CACHE.uri = repo.uri; REPO_CACHE.hora = Date.now();
  return matriz;
}
/* Repositorios de datos madre: la empresa debe llenar dos; el primero ya está en uso y el segundo queda registrado a la espera de sus datos */
