function RepositoriosDatos({ onCargar, onLeer, cargando }) {
  const { datos, usuario, dispatch } = useApp();
  const toast = useToast();
  const lista = (datos.config.repositorios && datos.config.repositorios.length ? datos.config.repositorios : REPOSITORIOS_INICIALES);
  const [f, setF] = useState(lista);
  const edita = ['rrhh', 'admin'].includes(usuario.rol);
  const fichas = datos.fichas || [];
  const guardar = () => {
    dispatch({ type: 'ACTUALIZAR_CONFIG', payload: { config: { repositorios: f.map((x) => ({ ...x, modulos: x.modulos || [], estado: x.url.trim() ? 'ACTIVO' : 'PENDIENTE' })) }, bitacora: registro(usuario.id, 'EDITAR', 'Configuración', 'repositorios', `Repositorios de datos actualizados (${f.length})`) } });
    toast('Repositorios guardados.');
  };
  const cambia = (id, k, v) => setF((x) => x.map((y) => (y.id === id ? { ...y, [k]: v } : y)));
  const agregar = () => {
    if (f.length >= MAX_REPOSITORIOS) { toast(`El sistema admite hasta ${MAX_REPOSITORIOS} repositorios.`, 'error'); return; }
    let n = f.length + 1; while (f.some((y) => y.id === `R${n}`)) n += 1;
    setF((x) => [...x, { id: `R${n}`, modulos: [], nombre: `Repositorio ${n} (por definir)`, url: '', contenido: '', estado: 'PENDIENTE' }]);
  };
  return (
    <div className="flex flex-col gap-3">
      <Panel titulo={`Repositorios de datos (${f.length} de ${MAX_REPOSITORIOS})`} accion={edita ? <div className="flex gap-2"><Boton icono={Plus} tamano="sm" variante="secundario" disabled={f.length >= MAX_REPOSITORIOS} onClick={agregar}>Agregar repositorio</Boton><Boton icono={Save} tamano="sm" onClick={guardar}>Guardar</Boton></div> : null}>
        <p className={`mb-3 text-sm ${UI.tenue}`}>El sistema admite hasta {MAX_REPOSITORIOS} repositorios de información. Indique para cada uno el enlace y los módulos que lo usan. Del repositorio de fichas se toman los datos de los trabajadores: si una cédula tiene más de un registro se pregunta si desea actualizar los datos y se toma el más reciente.</p>
        <ul className="m-0 flex list-none flex-col gap-3 p-0">
          {f.map((r, i) => (
            <li key={r.id} className={`rounded-md border p-3 ${UI.borde}`}>
              <div className="mb-2 flex flex-wrap items-center gap-2"><span className={`text-sm font-semibold ${UI.tinta}`}>{`Repositorio ${i + 1}`}</span><Badge tono={r.url.trim() ? 'exito' : 'alerta'}>{r.url.trim() ? 'En uso' : 'Pendiente'}</Badge>
                {edita && !r.uri ? <Boton tamano="sm" variante="fantasma" icono={X} className="ml-auto" onClick={() => setF((x) => x.filter((y) => y.id !== r.id))}>Quitar</Boton> : null}</div>
              <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                <Campo etiqueta="Nombre" htmlFor={`rep-${r.id}-n`}><input id={`rep-${r.id}-n`} className={UI.input} disabled={!edita} value={r.nombre} onChange={(e) => cambia(r.id, 'nombre', e.target.value)} /></Campo>
                <Campo etiqueta="Contenido" htmlFor={`rep-${r.id}-c`}><input id={`rep-${r.id}-c`} className={UI.input} disabled={!edita} value={r.contenido} onChange={(e) => cambia(r.id, 'contenido', e.target.value)} /></Campo>
                <div className="sm:col-span-2"><Campo etiqueta="Dirección (enlace de SharePoint)" htmlFor={`rep-${r.id}-u`}><input id={`rep-${r.id}-u`} className={UI.input} disabled={!edita} placeholder="Pegue aquí el enlace cuando esté disponible" value={r.url} onChange={(e) => cambia(r.id, 'url', e.target.value)} /></Campo></div>
                <div className="sm:col-span-2">
                  <p className={`mb-1 text-xs font-semibold uppercase tracking-wide ${UI.tenue}`}>Módulos que lo usan</p>
                  <div className="grid grid-cols-1 gap-1 sm:grid-cols-3">
                    {MODULOS_REPOSITORIO.map((m) => (
                      <label key={m.id} htmlFor={`rep-${r.id}-m-${m.id}`} className={`flex items-center gap-2 text-sm ${UI.tinta}`}>
                        <input id={`rep-${r.id}-m-${m.id}`} type="checkbox" className="h-4 w-4 accent-[#6B1E3F]" disabled={!edita} checked={(r.modulos || []).includes(m.id)} onChange={(e) => cambia(r.id, 'modulos', e.target.checked ? [...(r.modulos || []), m.id] : (r.modulos || []).filter((y) => y !== m.id))} />{m.texto}
                      </label>
                    ))}
                  </div>
                  <p className={`mb-0 mt-1 text-xs ${UI.tenue}`}>{(r.modulos || []).length ? `Lo usan: ${(r.modulos || []).map((id) => (MODULOS_REPOSITORIO.find((m) => m.id === id) || {}).texto || id).join(', ')}.` : 'Todavía no lo usa ningún módulo.'}</p>
                </div>
              </div>
              {r.id === 'R1' ? <p className={`mb-0 mt-2 text-xs ${UI.tenue}`}>{`${fichas.length} fichas cargadas en el sistema. `}{edita ? <button type="button" className="font-medium text-[#6B1E3F] underline" onClick={onCargar}>Cargar o actualizar desde el archivo</button> : null}</p> : null}
              {r.uri && edita ? <div className="mt-2"><Boton tamano="sm" icono={RefreshCw} disabled={cargando} onClick={() => onLeer(r)}>Leer del repositorio ahora</Boton></div> : null}
            </li>
          ))}
        </ul>
      </Panel>
    </div>
  );
}

function SincronizacionDatos() {
  const { datos, usuario, dispatch, nombreTienda, nombreCargo } = useApp();
  const { ir } = useNav();
  const toast = useToast();
  const [pestana, setPestana] = useState('estado');
  const [vista, setVista] = useState(null);
  const [alta, setAlta] = useState(null);
  const [fEstado, setFEstado] = useState('');
  const [busca, setBusca] = useState('');
  const [cargando, setCargando] = useState(false);
  const [sinFichaOk, setSinFichaOk] = useState(true);
  const [recibidos, setRecibidos] = useState(null); /* ids de la recepción automática que se están revisando */
  const [integ, setInteg] = useState({ pendientes: null, clave: '', ocupado: false });
  if (!['rrhh', 'admin'].includes(usuario.rol)) return <EstadoVacio icono={Lock} titulo="Sin acceso" texto="La sincronización de datos la realiza RRHH." />;
  const fichas = datos.fichas || [];
  const porCedula = new Map(datos.trabajadores.map((tr) => [soloDigitos(tr.cedula), tr]));
  const estadoFicha = (f) => (porCedula.get(f.cedula) ? 'VINCULADA' : /oficina/i.test(f.entorno || '') ? 'OFICINA' : !f.tiendaId || !f.cargoId ? 'INCOMPLETA' : 'SIN_INGRESO');
  const TEXTO_ESTADO = { VINCULADA: ['En el sistema', 'exito'], SIN_INGRESO: ['Falta fecha de ingreso', 'alerta'], INCOMPLETA: ['Falta tienda o cargo', 'peligro'], OFICINA: ['Oficinas administrativas', 'neutro'] };
  const conteo = (e) => fichas.filter((f) => estadoFicha(f) === e).length;
  const filas = fichas.filter((f) => (!fEstado || estadoFicha(f) === fEstado) && (!busca || `${f.cedula} ${f.nombres} ${f.apellidos} ${f.tiendaTexto}`.toLowerCase().includes(busca.toLowerCase())))
    .sort((a, b) => `${a.apellidos} ${a.nombres}`.localeCompare(`${b.apellidos} ${b.nombres}`));

  const leerArchivo = async (archivo) => {
    const nombre = archivo.name.toLowerCase();
    const leer = (modo) => new Promise((ok, falla) => { const r = new FileReader(); r.onload = () => ok(r.result); r.onerror = () => falla(r.error || new Error('lectura fallida')); if (modo === 'texto') r.readAsText(archivo, 'utf-8'); else r.readAsArrayBuffer(archivo); });
    if (nombre.endsWith('.csv') || nombre.endsWith('.txt')) {
      const texto = await leer('texto');
      const sep = (texto.split('\n')[0].match(/;/g) || []).length > (texto.split('\n')[0].match(/,/g) || []).length ? ';' : texto.includes('\t') ? '\t' : ',';
      return texto.replace(/^﻿/, '').split(/\r?\n/).map((l) => l.split(sep).map((c) => c.replace(/^"|"$/g, '').trim()));
    }
    const XLSX = await cargarLibreria(SHEETJS_URL, 'XLSX');
    const libro = XLSX.read(await leer('buffer'), { type: 'array' });
    const hoja = libro.Sheets[libro.SheetNames[0]];
    return XLSX.utils.sheet_to_json(hoja, { header: 1, raw: true, defval: '' });
  };
  const armarVista = (matriz, nombreFuente) => {
    const { fichas: nuevas0, avisos, duplicadas = [] } = fichasDesdeFormulario(matriz, `Formulario de actualización de datos (${nombreFuente})`);
    const nuevas = usuario.rol === 'rrhh' ? nuevas0 : nuevas0.map(({ discapacidad, ...x }) => x); /* lo sensible solo lo carga RRHH */
    const existentes = new Set(fichas.map((f) => f.id));
    setVista({ tipo: 'formulario', nuevas, avisos, duplicadas, decisiones: Object.fromEntries(duplicadas.map((x) => [x.cedula, true])), altas: nuevas.filter((f) => !existentes.has(f.id)).length, actualizadas: nuevas.filter((f) => existentes.has(f.id)).length, archivo: nombreFuente });
    setPestana('formulario');
  };
  /* Lectura directa del repositorio de SharePoint con el conector de Microsoft 365 (disponible al abrir el sistema desde Claude) */
  const leerRepositorio = async (repo) => {
    setRecibidos(null);
    setCargando(true);
    try {
      const matriz = await leerMatrizRepositorio(repo, true);
      armarVista(matriz, repo.nombre);
    } catch (err) { toast(`No se pudo leer el repositorio: ${err.message || err.code}`, 'error'); }
    setCargando(false);
  };
  /* Recepción automática: filas que Power Automate envía a la nube cuando cambia el Excel de SharePoint */
  const contarRecibido = async () => {
    if (!NUBE) return;
    try { const f = await NUBE.formularioPendiente(); setInteg((x) => ({ ...x, pendientes: f.length })); } catch (err) { toast(`No se pudo consultar lo recibido: ${err.message}`, 'error'); }
  };
  const revisarRecibido = async () => {
    setCargando(true);
    try {
      const filas = await NUBE.formularioPendiente();
      if (!filas.length) { toast('No hay respuestas nuevas por revisar.'); setInteg((x) => ({ ...x, pendientes: 0 })); setCargando(false); return; }
      const encab = []; filas.forEach((f) => Object.keys(f.data || {}).forEach((k) => { if (!encab.includes(k)) encab.push(k); }));
      const matriz = [encab, ...filas.map((f) => encab.map((k) => (f.data[k] === null || f.data[k] === undefined ? '' : f.data[k])))];
      setRecibidos(filas.map((f) => f.id_formulario));
      armarVista(matriz, 'recepción automática');
    } catch (err) { toast(`No se pudo leer lo recibido: ${err.message}`, 'error'); }
    setCargando(false);
  };
  const generarClave = async () => {
    setInteg((x) => ({ ...x, ocupado: true }));
    try { const k = await NUBE.generarClaveIntegracion(); setInteg((x) => ({ ...x, clave: k, ocupado: false })); }
    catch (err) { toast(`No se pudo generar la clave: ${err.message}`, 'error'); setInteg((x) => ({ ...x, ocupado: false })); }
  };
  const copiarTexto = async (t) => { try { await navigator.clipboard.writeText(t); toast('Copiado.'); } catch (e) { toast('Seleccione y copie el texto manualmente.', 'error'); } };
  const cargarFormulario = async (e) => {
    const archivo = e.target.files && e.target.files[0]; e.target.value = '';
    if (!archivo) return;
    setRecibidos(null);
    setCargando(true);
    try {
      armarVista(await leerArchivo(archivo), archivo.name);
    } catch (err) { toast(`No se pudo leer el archivo: ${err.message}`, 'error'); }
    setCargando(false);
  };
  const confirmarFormulario = () => {
    const previas = new Map(fichas.map((f) => [f.id, f]));
    const dupPor = new Map((vista.duplicadas || []).map((x) => [x.cedula, x]));
    const lista = [];
    vista.nuevas.forEach((f0) => {
      const d = dupPor.get(f0.id);
      const actualizar = !d || (vista.decisiones || {})[d.cedula] !== false;
      const p = previas.get(f0.id);
      if (!actualizar && p) return; /* el usuario decidió no actualizar: queda la ficha que ya estaba */
      if (p && (p.respuestaTs || 0) > (f0.respuestaTs || 0)) return; /* la ficha guardada es más reciente que esta respuesta: gana siempre la última */
      const f = !actualizar ? { ...d.anterior, numRegistros: f0.numRegistros, respuestasPrevias: f0.respuestasPrevias } : f0;
      lista.push(p ? { ...p, ...f, tiendaId: f.tiendaId || p.tiendaId, cargoId: f.cargoId || p.cargoId, trabajadorId: p.trabajadorId || '' } : f);
    });
    dispatch({ type: 'GUARDAR_FICHAS', payload: { fichas: lista, bitacora: registro(usuario.id, 'SINCRONIZAR', 'Fichas personales', '-', `${vista.archivo}: ${vista.altas} nuevas y ${vista.actualizadas} actualizadas`) } });
    toast(`Fichas sincronizadas: ${vista.altas} nuevas y ${vista.actualizadas} actualizadas.`);
    if (recibidos && recibidos.length && NUBE) NUBE.formularioMarcar(recibidos).catch((e) => toast(`No se pudo marcar lo recibido como procesado: ${e.message}`, 'error'));
    setRecibidos(null);
    setVista(null); setPestana('estado');
  };
  const cargarSalidas = async (e) => {
    const archivo = e.target.files && e.target.files[0]; e.target.value = '';
    if (!archivo) return;
    setCargando(true);
    try {
      let r = { filas: [], avisos: [] };
      for (const m of await leerArchivoHojas(archivo)) { r = entrevistasDesdeFormulario(m, `Entrevista de salida (${archivo.name})`); if (r.filas.length) break; }
      if (!r.filas.length) { toast(r.avisos[0] || 'El archivo no tiene respuestas de la entrevista de salida.', 'error'); setCargando(false); return; }
      const previas = new Map((datos.entrevistasSalida || []).map((x) => [x.id, x]));
      const umbralC = Number(datos.config.umbralEgresoCritico) || 4;
      /* Clasificación por tienda: primero el expediente del trabajador (misma cédula); si no, el lugar que indicó en la entrevista */
      const filas = r.filas.map((x) => {
        const tr = x.cedula ? porCedula.get(x.cedula) : null;
        const prev = previas.get(x.id);
        const tiendaId = (tr && tr.tiendaId) || x.tiendaId || (prev && prev.tiendaId) || '';
        return { ...x, trabajadorId: tr ? tr.id : '', tiendaId, cargoId: x.cargoId || (tr ? tr.cargoId : '') };
      });
      setVista({ tipo: 'salidas', filas, avisos: r.avisos, nuevas: filas.filter((x) => !previas.has(x.id)).length, actualizadas: filas.filter((x) => previas.has(x.id)).length, sinTienda: filas.filter((x) => !x.tiendaId).length, criticas: filas.filter((x) => esCritica(x, umbralC)).length, umbralC, archivo: archivo.name });
    } catch (err) { toast(`No se pudo leer el archivo: ${err.message}`, 'error'); }
    setCargando(false);
  };
  const leerSalidasNube = async () => {
    setCargando(true);
    try {
      const matriz = await leerMatrizRepositorio({ uri: URI_SALIDAS }, true);
      const r = entrevistasDesdeFormulario(matriz, `Entrevista de salida (${NOMBRE_SALIDAS})`);
      if (!r.filas.length) { toast(r.avisos[0] || 'El archivo no tiene respuestas de la entrevista de salida.', 'error'); setCargando(false); return; }
      const previas = new Map((datos.entrevistasSalida || []).map((x) => [x.id, x]));
      const umbralC = Number(datos.config.umbralEgresoCritico) || 4;
      const filas = filasSalidasClasificadas(r.filas, datos);
      setVista({ tipo: 'salidas', filas, avisos: r.avisos, nuevas: filas.filter((x) => !previas.has(x.id)).length, actualizadas: filas.filter((x) => previas.has(x.id)).length, sinTienda: filas.filter((x) => !x.tiendaId).length, criticas: filas.filter((x) => esCritica(x, umbralC)).length, umbralC, archivo: NOMBRE_SALIDAS });
    } catch (err) { toast(`No se pudo leer el archivo: ${err.message || err.code}`, 'error'); }
    setCargando(false);
  };
  const confirmarSalidas = () => {
    dispatch({ type: 'GUARDAR_SALIDAS', payload: { entrevistas: vista.filas, bitacora: registro(usuario.id, 'SINCRONIZAR', 'Entrevistas de salida', '-', `${vista.archivo}: ${vista.nuevas} nuevas, ${vista.actualizadas} actualizadas, ${vista.criticas} críticas`) } });
    toast(`Entrevistas cargadas: ${vista.nuevas} nuevas y ${vista.actualizadas} actualizadas.`);
    setVista(null); setPestana('salidas');
  };
  const cargarBI = async (e) => {
    const archivo = e.target.files && e.target.files[0]; e.target.value = '';
    if (!archivo) return;
    setCargando(true);
    try {
      /* El reporte de BI puede traer varias hojas (Planeta, Balú, estructura): se leen todas las que tengan Cédula e Ingreso. */
      const vistos = new Set(); const lineas = []; const avisos = [];
      (await leerArchivoHojas(archivo)).forEach((m) => {
        const r = ingresosDesdeBI(m);
        if (!r.filas.length) return;
        r.filas.forEach((l) => { if (!vistos.has(l.cedula)) { vistos.add(l.cedula); lineas.push(l); } });
        avisos.push(...r.avisos);
      });
      if (!lineas.length) { toast('El archivo no tiene filas con Cédula y Fecha de ingreso (en BI: columnas "Cédula" e "Ingreso").', 'error'); setCargando(false); return; }
      const fichasMap = new Map(fichas.map((f) => [f.id, f]));
      const listos = []; const sinFicha = []; const yaExisten = []; const incompletos = []; const creables = [];
      lineas.forEach((l) => {
        if (porCedula.get(l.cedula)) { yaExisten.push(l); return; }
        const f = fichasMap.get(l.cedula);
        if (!f) {
          sinFicha.push(l);
          const tid = tiendaDesdeTexto(l.tiendaTexto, l.marca);
          if (l.apellidos && tid && l.cargoId) creables.push({ ficha: { id: l.cedula, cedula: l.cedula, letra: l.letra, nombres: l.nombres, apellidos: l.apellidos, genero: l.genero }, fechaIngreso: l.fechaIngreso, tiendaId: tid, cargoId: l.cargoId });
          else incompletos.push({ ...l, nombre: `${l.apellidos || l.cedula}${l.nombres ? `, ${l.nombres}` : ''}`, motivo: !tid ? `tienda no reconocida (${l.tiendaTexto || 'sin dato'})` : `cargo no reconocido (${l.cargoTexto || 'sin dato'})` });
          return;
        }
        const tiendaId = f.tiendaId || tiendaDesdeTexto(l.tiendaTexto, l.marca || f.marca);
        const cargoId = l.cargoId || f.cargoId;
        if (!tiendaId || !cargoId) { incompletos.push({ ...l, nombre: `${f.apellidos}, ${f.nombres}`, motivo: !tiendaId ? `tienda no reconocida (${l.tiendaTexto || 'sin dato'})` : `cargo no reconocido (${l.cargoTexto || 'sin dato'})` }); return; }
        listos.push({ ficha: f, fechaIngreso: l.fechaIngreso, tiendaId, cargoId });
      });
      setVista({ tipo: 'bi', listos, creables, sinFicha, yaExisten, incompletos, avisos, archivo: archivo.name });
    } catch (err) { toast(`No se pudo leer el archivo: ${err.message}`, 'error'); }
    setCargando(false);
  };
  const confirmarBI = () => {
    const altas = [...vista.listos, ...(sinFichaOk ? vista.creables : [])];
    const trabajadores = altas.map((x) => trabajadorDesdeFicha(x.ficha, x.fechaIngreso, x.cargoId, x.tiendaId, datos));
    dispatch({ type: 'ALTA_TRABAJADORES', payload: { trabajadores, bitacora: registro(usuario.id, 'SINCRONIZAR', 'Trabajadores', '-', `${vista.archivo}: ${trabajadores.length} altas con fecha de ingreso de BI`) } });
    toast(`${trabajadores.length} trabajadores dados de alta.`);
    setVista(null); setPestana('estado');
  };
  const confirmarAlta = () => {
    const err = {};
    if (!alta.fechaIngreso || alta.fechaIngreso > hoyISO()) err.fechaIngreso = 'Indique la fecha de ingreso (no futura).';
    if (!alta.tiendaId) err.tiendaId = 'Seleccione la tienda.';
    if (!alta.cargoId) err.cargoId = 'Seleccione el cargo.';
    if (Object.keys(err).length) { setAlta((x) => ({ ...x, errores: err })); return; }
    const f = fichas.find((x) => x.id === alta.cedula);
    const tr = trabajadorDesdeFicha(f, alta.fechaIngreso, alta.cargoId, alta.tiendaId, datos);
    dispatch({ type: 'ALTA_TRABAJADORES', payload: { trabajadores: [tr], fichas: [{ ...f, tiendaId: alta.tiendaId, cargoId: alta.cargoId }], bitacora: registro(usuario.id, 'CREAR', 'Trabajador', tr.id, `Alta desde ficha: ${tr.nombres} ${tr.apellidos} · ingreso ${formatearFecha(alta.fechaIngreso)}`) } });
    toast(`${tr.nombres} ${tr.apellidos} quedó registrado en ${nombreTienda(alta.tiendaId)}.`);
    setAlta(null);
  };
  const tiendasOrden = [...datos.tiendas].sort((a, b) => a.marca.localeCompare(b.marca) || a.nombre.localeCompare(b.nombre));

  return (
    <div>
      <Encabezado titulo="Sincronización de datos" subtitulo="Fichas del formulario de actualización de datos y altas con la fecha de ingreso de BI. Se cruzan por cédula. No se cargan datos bancarios." />
      <Pestanas activa={pestana} onCambiar={(v) => { setPestana(v); setVista(null); setRecibidos(null); }} opciones={[
        { id: 'estado', texto: 'Estado de las fichas', contador: fichas.length },
        { id: 'repositorios', texto: 'Repositorios de datos', contador: (datos.config.repositorios && datos.config.repositorios.length ? datos.config.repositorios : REPOSITORIOS_INICIALES).length },
        { id: 'formulario', texto: 'Cargar formulario' },
        ...(NUBE ? [{ id: 'automatico', texto: 'Recepción automática', contador: integ.pendientes || 0 }] : []),
        { id: 'bi', texto: 'Cargar fechas de ingreso (BI)' },
        { id: 'salidas', texto: 'Entrevistas de salida', contador: (datos.entrevistasSalida || []).length },
      ]} />
      {pestana === 'repositorios' ? <RepositoriosDatos onCargar={() => setPestana('formulario')} onLeer={leerRepositorio} cargando={cargando} /> : null}
      {pestana === 'estado' ? (
        <div className="flex flex-col gap-3">
          <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
            <Indicador icono={CheckCircle2} titulo="En el sistema" valor={String(conteo('VINCULADA'))} detalle="Ficha unida a su expediente" onClick={() => setFEstado('VINCULADA')} />
            <Indicador icono={Clock} titulo="Falta fecha de ingreso" valor={String(conteo('SIN_INGRESO'))} detalle="Cargue BI o dé de alta" tono={conteo('SIN_INGRESO') ? 'alerta' : 'normal'} onClick={() => setFEstado('SIN_INGRESO')} />
            <Indicador icono={AlertTriangle} titulo="Falta tienda o cargo" valor={String(conteo('INCOMPLETA'))} detalle="Revise y complete" tono={conteo('INCOMPLETA') ? 'alerta' : 'normal'} onClick={() => setFEstado('INCOMPLETA')} />
            <Indicador icono={Building2} titulo="Oficinas administrativas" valor={String(conteo('OFICINA'))} detalle="Fuera de la plantilla de tiendas" onClick={() => setFEstado('OFICINA')} />
          </div>
          <div className="flex flex-wrap gap-2">
            <select id="sd-estado" className={`${UI.input} w-auto`} value={fEstado} onChange={(e) => setFEstado(e.target.value)} aria-label="Filtrar por estado">
              <option value="">Todos los estados</option>
              {Object.keys(TEXTO_ESTADO).map((k) => <option key={k} value={k}>{TEXTO_ESTADO[k][0]}</option>)}
            </select>
            <input id="sd-busca" className={`${UI.input} sm:max-w-xs`} placeholder="Buscar cédula, nombre o tienda" value={busca} onChange={(e) => setBusca(e.target.value)} aria-label="Buscar ficha" />
            {usuario.rol === 'rrhh' ? <Boton variante="secundario" icono={FileDown} disabled={!fichas.length} onClick={async () => { try { const { blob, filas: n } = await exportarFichasExcel(datos); const r = await guardarArchivo(blob, `datos-precargados-${hoyISO()}.xlsx`); toast(...(r === 'ok' ? [`Se exportaron ${n} fichas en Excel.`, 'exito'] : MENSAJE_GUARDADO[r])); } catch (e) { toast('No se pudo generar el Excel.', 'error'); } }}>Exportar datos precargados (Excel)</Boton> : null}
          </div>
          <Tabla filas={filas} vacio={<EstadoVacio icono={Database} titulo="Sin fichas" texto="Cargue el Excel del formulario de actualización de datos en la pestaña “Cargar formulario”." />} columnas={[
            { clave: 'cedula', titulo: 'Cédula', clase: 'font-mono tabular-nums whitespace-nowrap' },
            { clave: 'nombre', titulo: 'Nombre', render: (f) => `${f.apellidos}, ${f.nombres}` },
            { clave: 'tienda', titulo: 'Tienda', render: (f) => (f.tiendaId ? nombreTienda(f.tiendaId) : <span className={UI.tenue}>{f.tiendaTexto || '—'}</span>) },
            { clave: 'cargo', titulo: 'Cargo', render: (f) => (f.cargoId ? nombreCargo(f.cargoId) : <span className={UI.tenue}>{f.cargoTexto || '—'}</span>) },
            { clave: 'estado', titulo: 'Estado', render: (f) => { const e = estadoFicha(f); return <Badge tono={TEXTO_ESTADO[e][1]}>{TEXTO_ESTADO[e][0]}</Badge>; } },
            { clave: 'acc', titulo: '', render: (f) => (estadoFicha(f) === 'VINCULADA' ? null : <Boton tamano="sm" variante="secundario" icono={UserPlus} onClick={() => setAlta({ cedula: f.id, fechaIngreso: '', tiendaId: f.tiendaId || '', cargoId: f.cargoId || '', errores: {} })}>Dar de alta</Boton>) },
          ]} />
        </div>
      ) : null}
      {pestana === 'automatico' && !vista && NUBE ? (() => {
        const di = NUBE.datosIntegracion();
        return (
          <Panel titulo="Recepción automática del formulario (Power Automate)">
            <p className={`mb-3 text-sm ${UI.tinta}`}>Cuando alguien responde o corrige el formulario, un flujo de Power Automate envía la fila a este sistema. Aquí usted revisa lo recibido y lo aplica: si una cédula aparece repetida, <b>se conserva siempre la respuesta más reciente</b> (fecha y hora). No se reciben cuentas bancarias.</p>
            <div className="flex flex-wrap items-center gap-2">
              <Boton icono={RefreshCw} onClick={revisarRecibido} disabled={cargando}>{cargando ? 'Leyendo…' : 'Revisar respuestas recibidas'}</Boton>
              <Boton variante="secundario" onClick={contarRecibido}>Consultar cuántas hay</Boton>
              {integ.pendientes !== null ? <span className={`text-sm ${UI.tenue}`}>{integ.pendientes} por revisar</span> : null}
            </div>
            <h3 className={`mt-6 text-sm font-semibold ${UI.tinta}`}>Datos para configurar el flujo (TI)</h3>
            <p className={`mb-2 mt-1 text-xs ${UI.tenue}`}>Acción «HTTP» de Power Automate: método POST, cuerpo JSON con el campo <code>p_filas</code> (las columnas del Excel como pares nombre-valor) y el campo <code>p_clave</code>. Encabezados: <code>apikey</code>, <code>Authorization: Bearer</code> con el mismo valor, y <code>Content-Type: application/json</code>.</p>
            <dl className="grid gap-2 text-xs">
              <div><dt className={UI.tenue}>Dirección (URL)</dt><dd className="flex items-center gap-2"><code className="min-w-0 break-all rounded bg-[#F5F1F7] px-2 py-1">{di.url}</code><Boton tamano="sm" variante="secundario" icono={Copy} onClick={() => copiarTexto(di.url)}>Copiar</Boton></dd></div>
              <div><dt className={UI.tenue}>apikey (pública)</dt><dd className="flex items-center gap-2"><code className="min-w-0 break-all rounded bg-[#F5F1F7] px-2 py-1">{di.apikey}</code><Boton tamano="sm" variante="secundario" icono={Copy} onClick={() => copiarTexto(di.apikey)}>Copiar</Boton></dd></div>
            </dl>
            <div className="mt-4 rounded-lg border border-[#E4DFE7] p-3">
              <p className={`text-sm ${UI.tinta}`}><b>Clave de integración.</b> Se muestra una sola vez; guárdela directamente en Power Automate. Si genera otra, la anterior deja de funcionar.</p>
              {integ.clave ? (
                <div className="mt-2 flex items-center gap-2"><code className="min-w-0 break-all rounded bg-[#F5F1F7] px-2 py-1 text-xs">{integ.clave}</code><Boton tamano="sm" variante="secundario" icono={Copy} onClick={() => copiarTexto(integ.clave)}>Copiar</Boton></div>
              ) : <Boton className="mt-2" variante="secundario" onClick={generarClave} disabled={integ.ocupado}>{integ.ocupado ? 'Generando…' : 'Generar clave de integración'}</Boton>}
            </div>
          </Panel>
        );
      })() : null}
      {pestana === 'formulario' && !vista ? (
        <Panel titulo="Formulario “Jornada de Actualización de datos Futura Retail”">
          <p className={`mb-3 text-sm ${UI.tinta}`}>Descargue el Excel desde SharePoint (Archivo → Guardar como → Descargar una copia) y cárguelo aquí. Se actualizan datos personales y de contacto, familia y emergencia, tallas y educación. Si una cédula responde varias veces, se toma la respuesta más reciente.</p>
          <label htmlFor="sd-form" className={`inline-flex cursor-pointer items-center gap-2 rounded-md px-3.5 py-2 text-sm font-medium ${UI.btnPrimario}`}>{cargando ? <Loader2 size={16} className="animate-spin" /> : <FileDown size={16} />}Seleccionar Excel</label>
          <input id="sd-form" type="file" accept=".xlsx,.xls,.csv" className="sr-only" onChange={cargarFormulario} />
        </Panel>
      ) : null}
      {pestana === 'bi' && !vista ? (
        <Panel titulo="Fechas de ingreso desde BI">
          <p className={`mb-3 text-sm ${UI.tinta}`}>Cargue el reporte de personal activo de BI en Excel o CSV (columnas <b>Cédula</b> e <b>Ingreso</b>; también se leen Apellido y Nombre, Cargo, Ubicación y Marca). Si el Excel trae varias hojas, se leen todas las que tengan esas columnas. Quien tiene ficha se da de alta con esa fecha; quien aún no llenó el formulario puede darse de alta con los datos del reporte. Quien ya está en el sistema no se modifica.</p>
          <label htmlFor="sd-bi" className={`inline-flex cursor-pointer items-center gap-2 rounded-md px-3.5 py-2 text-sm font-medium ${UI.btnPrimario}`}>{cargando ? <Loader2 size={16} className="animate-spin" /> : <FileDown size={16} />}Seleccionar archivo de BI</label>
          <input id="sd-bi" type="file" accept=".xlsx,.xls,.csv,.txt" className="sr-only" onChange={cargarBI} />
        </Panel>
      ) : null}
      {pestana === 'salidas' && !vista ? (
        <Panel titulo="Entrevistas de salida (Microsoft Forms)">
          <p className={`mb-3 text-sm ${UI.tinta}`}>Descargue el Excel «Entrevista de Salida» desde SharePoint (Archivo → Guardar como → Descargar una copia) y cárguelo aquí. Se toman el motivo de la salida, los aspectos positivo y negativo, el tema a mejorar y los puntos de cada respuesta. Cada entrevista se clasifica por tienda (por la cédula del trabajador o por el lugar indicado) y es <b>crítica</b> si su total supera {Number(datos.config.umbralEgresoCritico) || 4} puntos. Si se vuelve a cargar el mismo archivo, no se duplican: se actualizan por su Id.</p>
          <p className={`mb-3 text-xs ${UI.tenue}`}>Contiene datos personales (nombre y cédula): los ve solo RRHH; los demás perfiles ven la tienda, el cargo y las causas. Los datos reales deben cargarse en la versión con Supabase.</p>
          <div className="mb-3"><Boton icono={RefreshCw} onClick={leerSalidasNube} disabled={cargando}>Leer resultados de la encuesta de salida ahora</Boton></div>
          <label htmlFor="sd-salidas" className={`inline-flex cursor-pointer items-center gap-2 rounded-md px-3.5 py-2 text-sm font-medium ${UI.btnPrimario}`}>{cargando ? <Loader2 size={16} className="animate-spin" /> : <FileDown size={16} />}Seleccionar Excel de entrevistas</label>
          <input id="sd-salidas" type="file" accept=".xlsx,.xls,.csv" className="sr-only" onChange={cargarSalidas} />
          {(datos.entrevistasSalida || []).length ? <div className="mt-4"><Boton variante="secundario" icono={Eye} onClick={() => ir('informes', { modulo: 'salidas' })}>{`Ver ${(datos.entrevistasSalida || []).length} entrevistas en Informes`}</Boton></div> : null}
        </Panel>
      ) : null}
      {vista && vista.tipo === 'salidas' ? (
        <Panel titulo={`Vista previa · ${vista.archivo}`}>
          <dl className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <Dato etiqueta="Entrevistas en el archivo" valor={String(vista.filas.length)} />
            <Dato etiqueta="Nuevas" valor={String(vista.nuevas)} />
            <Dato etiqueta={`Críticas (más de ${vista.umbralC} puntos)`} valor={String(vista.criticas)} />
            <Dato etiqueta="Sin tienda reconocida" valor={String(vista.sinTienda)} />
          </dl>
          {vista.sinTienda ? <p className="mt-3 text-xs text-amber-800">Las entrevistas sin tienda quedan como «Sin clasificar» y RRHH puede asignarles la tienda en Informes › Egresos críticos.</p> : null}
          {vista.avisos.length ? <ul className="mt-3 list-disc pl-5 text-xs text-amber-800">{vista.avisos.slice(0, 6).map((a) => <li key={a}>{a}</li>)}</ul> : null}
          <div className="mt-4 flex gap-2"><Boton icono={Save} onClick={confirmarSalidas}>Importar entrevistas</Boton><Boton variante="secundario" onClick={() => setVista(null)}>Cancelar</Boton></div>
        </Panel>
      ) : null}
      {vista && vista.tipo === 'formulario' ? (
        <Panel titulo={`Vista previa · ${vista.archivo}`}>
          <dl className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <Dato etiqueta="Personas en el archivo" valor={String(vista.nuevas.length)} />
            <Dato etiqueta="Fichas nuevas" valor={String(vista.altas)} />
            <Dato etiqueta="Fichas que se actualizan" valor={String(vista.actualizadas)} />
            <Dato etiqueta="Sin tienda reconocida" valor={String(vista.nuevas.filter((f) => !f.tiendaId).length)} />
            <Dato etiqueta="Con más de un registro" valor={String((vista.duplicadas || []).length)} />
          </dl>
          {(vista.duplicadas || []).length ? (
            <div className="mt-4 rounded-md border border-amber-300 bg-amber-50/70 p-3">
              <p className="m-0 flex items-center gap-1.5 text-sm font-semibold text-amber-900"><AlertTriangle size={16} aria-hidden="true" />{`${vista.duplicadas.length} ${vista.duplicadas.length === 1 ? 'persona tiene' : 'personas tienen'} más de un registro en el repositorio`}</p>
              <p className="mb-2 mt-1 text-sm text-amber-900">¿Desea actualizar los datos con el registro más reciente (el segundo)? Marque las que desea actualizar; las demás conservan los datos que ya estaban.</p>
              <div className="mb-2 flex gap-2">
                <Boton tamano="sm" variante="secundario" onClick={() => setVista((v) => ({ ...v, decisiones: Object.fromEntries(v.duplicadas.map((x) => [x.cedula, true])) }))}>Actualizar todas</Boton>
                <Boton tamano="sm" variante="secundario" onClick={() => setVista((v) => ({ ...v, decisiones: Object.fromEntries(v.duplicadas.map((x) => [x.cedula, false])) }))}>Mantener todas</Boton>
              </div>
              <ul className="m-0 flex max-h-64 list-none flex-col gap-1 overflow-y-auto p-0">
                {vista.duplicadas.map((x) => (
                  <li key={x.cedula}>
                    <label className="flex cursor-pointer items-start gap-2 text-sm">
                      <input type="checkbox" className="mt-0.5 h-4 w-4 accent-[#6B1E3F]" checked={vista.decisiones[x.cedula] !== false} onChange={(e) => setVista((v) => ({ ...v, decisiones: { ...v.decisiones, [x.cedula]: e.target.checked } }))} />
                      <span className="min-w-0 flex-1"><b>{x.nombre}</b> · {x.cedula} · {`${x.registros} registros (${x.fechas.map((fe) => formatearFecha(fe)).join(' y ')})`}{x.cambios.length ? ` · cambian: ${x.cambios.join(', ')}` : ' · sin diferencias'}</span>
                    </label>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
          {vista.avisos.length ? <ul className="mt-3 list-disc pl-5 text-xs text-amber-800">{vista.avisos.slice(0, 8).map((a) => <li key={a}>{a}</li>)}{vista.avisos.length > 8 ? <li>{`y ${vista.avisos.length - 8} avisos más`}</li> : null}</ul> : null}
          <div className="mt-4 flex gap-2"><Boton icono={Save} onClick={confirmarFormulario} disabled={!vista.nuevas.length}>Sincronizar fichas</Boton><Boton variante="secundario" onClick={() => setVista(null)}>Cancelar</Boton></div>
        </Panel>
      ) : null}
      {vista && vista.tipo === 'bi' ? (
        <Panel titulo={`Vista previa · ${vista.archivo}`}>
          <dl className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <Dato etiqueta="Con ficha, listos para alta" valor={String(vista.listos.length)} />
            <Dato etiqueta="Con información académica" valor={String(vista.listos.filter((x) => x.ficha && x.ficha.educacion).length)} />
            <Dato etiqueta="Ya en el sistema" valor={String(vista.yaExisten.length)} />
            <Dato etiqueta="Sin ficha del formulario" valor={String(vista.sinFicha.length)} />
            <Dato etiqueta="Falta tienda o cargo" valor={String(vista.incompletos.length)} />
          </dl>
          {vista.creables.length ? (
            <label htmlFor="sd-sinficha" className={`mt-3 flex items-start gap-2 text-sm ${UI.tinta}`}>
              <input id="sd-sinficha" type="checkbox" className="mt-0.5 h-4 w-4 accent-[#6B1E3F]" checked={sinFichaOk} onChange={(e) => setSinFichaOk(e.target.checked)} />
              <span>{`Dar de alta también a ${vista.creables.length} personas que aún no tienen ficha, con nombre, cargo, tienda e ingreso del reporte. Cuando llenen el formulario, su ficha se une por cédula.`}</span>
            </label>
          ) : null}
          {vista.sinFicha.length && !vista.creables.length ? <p className={`mt-3 text-xs ${UI.tenue}`}>{`Sin ficha (deben llenar el formulario o registrarse por Ingreso de personal): ${vista.sinFicha.slice(0, 15).map((x) => x.cedula).join(', ')}${vista.sinFicha.length > 15 ? '…' : ''}`}</p> : null}
          {vista.incompletos.length ? <p className="mt-2 text-xs text-amber-800">{`No se pudo dar de alta (${vista.incompletos.length}): ${vista.incompletos.slice(0, 8).map((x) => `${x.nombre} — ${x.motivo || 'falta tienda o cargo'}`).join('; ')}${vista.incompletos.length > 8 ? '…' : ''}`}</p> : null}
          {vista.avisos.length ? <ul className="mt-2 list-disc pl-5 text-xs text-amber-800">{vista.avisos.slice(0, 6).map((a) => <li key={a}>{a}</li>)}</ul> : null}
          <div className="mt-4 flex gap-2"><Boton icono={UserPlus} onClick={confirmarBI} disabled={!(vista.listos.length + (sinFichaOk ? vista.creables.length : 0))}>{`Dar de alta ${vista.listos.length + (sinFichaOk ? vista.creables.length : 0)}`}</Boton><Boton variante="secundario" onClick={() => setVista(null)}>Cancelar</Boton></div>
        </Panel>
      ) : null}
      <Modal abierto={Boolean(alta)} titulo="Dar de alta desde la ficha" onCerrar={() => setAlta(null)}
        pie={<><Boton variante="secundario" onClick={() => setAlta(null)}>Cancelar</Boton><Boton icono={UserPlus} onClick={confirmarAlta}>Dar de alta</Boton></>}>
        {alta ? (() => { const f = fichas.find((x) => x.id === alta.cedula); return (
          <div className="flex flex-col gap-3">
            <Dato etiqueta="Trabajador" valor={`${f.apellidos}, ${f.nombres} · C.I. ${f.cedula}`} />
            <p className={`text-xs ${UI.tenue}`}>{`Según el formulario: ${f.tiendaTexto || 'sin tienda'} · ${f.cargoTexto || 'sin cargo'}`}</p>
            <Campo etiqueta="Fecha de ingreso" htmlFor="sd-fi" error={alta.errores.fechaIngreso} requerido><input id="sd-fi" type="date" max={hoyISO()} className={UI.input} value={alta.fechaIngreso} onChange={(e) => setAlta((x) => ({ ...x, fechaIngreso: e.target.value }))} /></Campo>
            <Campo etiqueta="Tienda" htmlFor="sd-ti" error={alta.errores.tiendaId} requerido><select id="sd-ti" className={UI.input} value={alta.tiendaId} onChange={(e) => setAlta((x) => ({ ...x, tiendaId: e.target.value }))}><option value="">Seleccione…</option>{tiendasOrden.map((x) => <option key={x.id} value={x.id}>{MARCAS[x.marca]} · {x.nombre}</option>)}</select></Campo>
            <Campo etiqueta="Cargo" htmlFor="sd-cg" error={alta.errores.cargoId} requerido><select id="sd-cg" className={UI.input} value={alta.cargoId} onChange={(e) => setAlta((x) => ({ ...x, cargoId: e.target.value }))}><option value="">Seleccione…</option>{datos.cargos.map((c) => <option key={c.id} value={c.id}>{c.nombre}</option>)}</select></Campo>
          </div>
        ); })() : null}
      </Modal>
    </div>
  );
}

/* Ficha del trabajador en PDF: todos los datos precargados del formulario más los del expediente */
function fichaTrabajadorHTML(trab, f, datos, verSensibles = false) {
  const e = escaparHtml;
  const ti = (datos.tiendas || []).find((x) => x.id === trab.tiendaId) || {};
  const cg = (datos.cargos || []).find((x) => x.id === trab.cargoId) || {};
  const dir = [f.direccion && f.direccion.calle, f.direccion && f.direccion.sector, f.direccion && f.direccion.edificio, f.direccion && f.direccion.municipio, f.estadoResidencia].filter(Boolean).join(', ');
  const v = (x) => (x === undefined || x === null || String(x).trim() === '' ? '—' : e(x));
  const fecha = (x) => (x ? e(formatearFecha(x)) : '—');
  const par = (a, b, c, d) => `<tr><td style="width:19%;background:#f6f1f4;"><b>${a}</b></td><td style="width:31%;">${b}</td>${c === undefined ? '<td colspan="2"></td>' : `<td style="width:19%;background:#f6f1f4;"><b>${c}</b></td><td style="width:31%;">${d}</td>`}</tr>`;
  const sec = (t, filas) => `<h3 style="font-size:10.5pt;margin:12px 0 4px;color:#6B1E3F;text-transform:uppercase;letter-spacing:.4px;">${t}</h3><table>${filas}</table>`;
  const hijos = (f.hijos || []).length
    ? `<table><tr style="background:#f6f1f4;"><td><b>Hijo(a)</b></td><td><b>Fecha de nacimiento</b></td><td><b>Edad</b></td><td><b>Cédula</b></td></tr>${(f.hijos || []).map((h) => `<tr><td>${v(h.nombre)}</td><td>${fecha(h.fechaNacimiento)}</td><td>${h.fechaNacimiento ? `${calcularEdad(h.fechaNacimiento)} años` : '—'}</td><td>${v(h.cedula)}</td></tr>`).join('')}</table>`
    : '<p>Sin hijos registrados.</p>';
  const cuerpo = `${ESTILO_TABLAS_DOC}
    ${sec('Datos del trabajador en el sistema', par('Nombre', `${e(trab.nombres)} ${e(trab.apellidos)}`, 'Cédula', `${e(f.letra || 'V')}-${e(trab.cedula)}`) + par('Marca', v(MARCAS[trab.marca] || trab.marca), 'Estatus', v(trab.estatus)) + par('Tienda / sede', v(ti.nombre), 'Cargo', v(cg.nombre)) + par('Fecha de ingreso', fecha(trab.fechaIngreso), 'Correo del gerente', v(f.correoGerente)))}
    ${sec('Datos personales', par('Género', v(f.genero), 'Nacionalidad', v(f.nacionalidad)) + par('RIF', v(f.rif), 'Fecha de nacimiento', f.fechaNacimiento ? `${fecha(f.fechaNacimiento)} (${calcularEdad(f.fechaNacimiento)} años)` : '—') + par('Estado civil', v(f.estadoCivil), 'Zurdo', v(f.zurdo)) + par('Nacionalidad (detalle)', v(f.nacionalidadDetalle), '¿Tiene hijos?', v(f.tieneHijos)) + par('Tipo de vivienda', v(f.tipoVivienda), 'Código postal', v(f.codigoPostal)))}
    ${sec('Contacto y dirección', par('Teléfono', v(f.telefono), 'Correo', v(f.correo)) + `<tr><td style="background:#f6f1f4;"><b>Dirección</b></td><td colspan="3">${v(dir)}</td></tr>`)}
    ${sec('Contacto en caso de emergencia', `<tr><td style="width:19%;background:#f6f1f4;"><b>Contacto 1</b></td><td>${v(f.emergencia1)}</td></tr><tr><td style="background:#f6f1f4;"><b>Contacto 2</b></td><td>${v(f.emergencia2)}</td></tr>`)}
    ${sec('Datos familiares', par('Cónyuge', v(f.conyuge && f.conyuge.nombre), 'Cédula del cónyuge', v(f.conyuge && f.conyuge.cedula)) + par('Padres viven', v(f.padresViven), 'Cantidad de hijos', v(f.cantidadHijos || (f.hijos || []).length)) + par('Padre', v(f.padre), 'Madre', v(f.madre)))}
    <h3 style="font-size:10.5pt;margin:12px 0 4px;color:#6B1E3F;text-transform:uppercase;letter-spacing:.4px;">Hijos</h3>${hijos}
    ${sec('Educación', par('Último título', v(f.educacion), 'Educación complementaria', v(f.educacionComplementaria)))}
    ${sec('Tallas de dotación', par('Camisa', v(f.tallas && f.tallas.camisa), 'Pantalón', v(f.tallas && f.tallas.pantalon)) + par('Calzado', v(f.tallas && f.tallas.calzado), 'Entorno de trabajo', v(f.entorno)))}
    ${verSensibles ? sec('Datos sensibles (confidencial · solo RRHH)', par('Personal con discapacidad', v(f.discapacidad && f.discapacidad.tiene), '¿Inscrito en el CONAPDIS?', v(f.discapacidad && f.discapacidad.conapdis))) : ''}
    ${sec('Datos declarados en el formulario', par('Unidad de negocio', v(f.unidadNegocio), 'Estado donde labora', v(f.estadoLabora)) + par('Tienda indicada', v(f.tiendaTexto), 'Cargo indicado', v(f.cargoTexto)))}
    <p style="font-size:8.5pt;color:#555;margin-top:10px;">Fuente: ${v(f.fuente || 'formulario')}${f.respuesta ? ` · respuesta del ${fecha(f.respuesta)}` : ''}. Documento confidencial, emitido el ${e(formatearFecha(hoyISO()))}.</p>`;
  return envolverDocumento({ titulo: 'Ficha del trabajador', cuerpo, firmas: [], marca: trab.marca || ti.marca || 'BALU' });
}

/* Archivo plano (una fila por persona) con todos los datos precargados que se sincronizaron */
const ENCABEZADOS_FICHAS = ['Cédula', 'Letra', 'Nombres', 'Apellidos', 'Género', 'Nacionalidad', 'Zurdo', 'RIF', 'Fecha de nacimiento', 'Estado civil', 'Tipo de vivienda', 'Cónyuge', 'Cédula del cónyuge', 'Padres viven', 'Padre', 'Madre', 'Cantidad de hijos',
  'Hijo 1', 'Fecha nac. hijo 1', 'Cédula hijo 1', 'Hijo 2', 'Fecha nac. hijo 2', 'Cédula hijo 2', 'Hijo 3', 'Fecha nac. hijo 3', 'Cédula hijo 3', 'Hijo 4', 'Fecha nac. hijo 4', 'Cédula hijo 4',
  'Correo', 'Correo del gerente', 'Estado de residencia', 'Calle', 'Sector', 'Edificio / casa', 'Municipio', 'Teléfono', 'Código postal', 'Entorno de trabajo', 'Unidad de negocio', 'Marca', 'Estado donde labora', 'Tienda indicada', 'Tienda asignada', 'Cargo indicado', 'Cargo asignado',
  'Último título', 'Educación complementaria', 'Contacto de emergencia 1', 'Contacto de emergencia 2', 'Talla de camisa', 'Talla de pantalón', 'Talla de calzado', 'Nacionalidad (detalle)', '¿Tiene hijos?', 'Personal con discapacidad', '¿Inscrito en el CONAPDIS?', 'En el sistema', 'Estatus', 'Fecha de ingreso', ...MES_ANIO_COLS('ingreso'), 'Fecha de egreso', ...MES_ANIO_COLS('egreso'), 'Fecha de respuesta', 'Fuente'];
function filaFichaPlana(f, datos) {
  const tr = (datos.trabajadores || []).find((x) => soloDigitos(x.cedula) === f.cedula);
  const nt = (id) => ((datos.tiendas || []).find((x) => x.id === id) || {}).nombre || '';
  const nc = (id) => ((datos.cargos || []).find((x) => x.id === id) || {}).nombre || '';
  const h = (n) => { const x = (f.hijos || [])[n] || {}; return [x.nombre || '', x.fechaNacimiento || '', x.cedula || '']; };
  const d = f.direccion || {}; const t = f.tallas || {}; const c = f.conyuge || {};
  return [f.cedula, f.letra || '', f.nombres, f.apellidos, f.genero, f.nacionalidad, f.zurdo, f.rif, f.fechaNacimiento, f.estadoCivil, f.tipoVivienda, c.nombre || '', c.cedula || '', f.padresViven, f.padre, f.madre, f.cantidadHijos || (f.hijos || []).length || '',
    ...h(0), ...h(1), ...h(2), ...h(3),
    f.correo, f.correoGerente, f.estadoResidencia, d.calle, d.sector, d.edificio, d.municipio, f.telefono, f.codigoPostal, f.entorno, f.unidadNegocio, MARCAS[f.marca] || f.marca || '', f.estadoLabora, f.tiendaTexto, nt(tr ? tr.tiendaId : f.tiendaId), f.cargoTexto, nc(tr ? tr.cargoId : f.cargoId),
    f.educacion, f.educacionComplementaria, f.emergencia1, f.emergencia2, t.camisa, t.pantalon, t.calzado, f.nacionalidadDetalle, f.tieneHijos, (f.discapacidad || {}).tiene, (f.discapacidad || {}).conapdis, tr ? 'Sí' : 'No', tr ? tr.estatus : '', tr ? tr.fechaIngreso : '', ...mesAnio(tr && tr.fechaIngreso), tr ? tr.fechaEgreso || '' : '', ...mesAnio(tr && tr.fechaEgreso), f.respuesta, f.fuente].map((x) => (x === undefined || x === null ? '' : x));
}
async function exportarFichasExcel(datos) {
  const XLSX = await cargarLibreria(SHEETJS_URL, 'XLSX');
  const filas = [...(datos.fichas || [])].sort((a, b) => `${a.apellidos} ${a.nombres}`.localeCompare(`${b.apellidos} ${b.nombres}`)).map((f) => filaFichaPlana(f, datos));
  const hoja = XLSX.utils.aoa_to_sheet([ENCABEZADOS_FICHAS, ...filas]);
  hoja['!cols'] = ENCABEZADOS_FICHAS.map((h) => ({ wch: Math.min(34, Math.max(12, h.length + 2)) }));
  const libro = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(libro, hoja, 'Datos precargados');
  const bin = XLSX.write(libro, { bookType: 'xlsx', type: 'array' });
  return { blob: new Blob([bin], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), filas: filas.length };
}

