                      <Boton variante="secundario" tamano="sm" icono={Plus} onClick={() => setFm((x) => ({ ...x, hijos: [...x.hijos, { nombre: '', fechaNacimiento: '', cedula: '' }] }))}>Agregar hijo</Boton>
