      {nuevoPre ? <FormPrecargado inicial={nuevoPre} onCerrar={() => setNuevoPre(null)} onGuardar={(pc) => {
        dispatch({ type: 'AGREGAR_PRECARGADO', payload: { precargado: pc, bitacora: registro(usuario.id, 'CREAR', 'Precargado', pc.id, `${pc.nombres} ${pc.apellidos} (${pc.cedula}) para ${nombreTienda(pc.tiendaId)}`) } });
        setNuevoPre(null); setPestana('precargados'); toast('Persona agregada al listado precargado.');
      }} /> : null}
      <Confirmar abierto={Boolean(quitar)} titulo="Quitar del listado precargado" variante="peligro" textoConfirmar="Quitar"
        mensaje={quitar ? `${quitar.nombres} ${quitar.apellidos} (${quitar.cedula}) dejará de aparecer para la tienda ${nombreTienda(quitar.tiendaId)}.` : ''}
        onCancelar={() => setQuitar(null)} onConfirmar={() => { dispatch({ type: 'QUITAR_PRECARGADO', payload: { id: quitar.id, bitacora: registro(usuario.id, 'ELIMINAR', 'Precargado', quitar.id, `${quitar.cedula} retirado del listado`) } }); setQuitar(null); toast('Persona retirada del listado.'); }} />
